/* Card set: Mario Kart (generated from mkrt.csv by tools/csv-to-set.js schema, packaged for staging). */
CardSets.register({"id":"mkrt","name":"Mario Kart","code":"MKRT","description":"460 cards from three decades of Mario Kart — every racer, course, item and kart that matters, from Super Mario Kart's first Rainbow Road to Mario Kart World's open roads, blue shells and all.","theme":{"primary":"#e60012","secondary":"#171a21","artBackground":"#101218","artFit":"cover"},"pack":{"name":"Mario Kart Pack","emblem":"🏁","skin":"mkrt"},"cards":[{"name":"Mario","rarity":"chase","id":"mario","subtitle":"Racer","details":"The middleweight all-rounder who has raced in every Mario Kart game since the series began on the SNES in 1992.","image":"assets/sets/compress/mkrt__mario.webp"},{"name":"Princess Peach","rarity":"chase","id":"princess-peach","subtitle":"Racer","details":"The Mushroom Kingdom's princess, a lightweight racer listed simply as 'Princess' in her 1992 Super Mario Kart debut.","image":"assets/sets/compress/mkrt__princess-peach.webp"},{"name":"Yoshi","rarity":"chase","id":"yoshi","subtitle":"Racer","details":"Mario's dinosaur pal, a lightweight racer since 1992 whose many colour variants all count as the one and only Yoshi.","image":"assets/sets/compress/mkrt__yoshi.webp"},{"name":"Bowser","rarity":"chase","id":"bowser","subtitle":"Racer","details":"The Koopa King is the series' heavyweight villain, racing against Mario since Super Mario Kart started it all in 1992.","image":"https://mario.wiki.gallery/images/thumb/d/d9/Bowser_Artwork_-_Mario_Kart_8.png/320px-Bowser_Artwork_-_Mario_Kart_8.png"},{"name":"Rainbow Road (N64)","rarity":"chase","id":"rainbow-road-n64","subtitle":"Course","details":"Mario Kart 64's marathon Rainbow Road: the longest course of its era, a fenced rainbow climb through space under chain-light stars.","image":"assets/sets/compress/mkrt__rainbow-road-n64.webp"},{"name":"Waluigi Pinball","rarity":"chase","id":"waluigi-pinball","subtitle":"Course","details":"A giant pinball machine in Mario Kart DS: racers are the ball, bouncing between bumpers, flippers and a huge rolling steel sphere.","image":"https://mario.wiki.gallery/images/thumb/a/a8/MK8D_DS_Waluigi_Pinball.png/320px-MK8D_DS_Waluigi_Pinball.png"},{"name":"Coconut Mall","rarity":"chase","id":"coconut-mall","subtitle":"Course","details":"A shopping mall course in Mario Kart Wii: escalators, palm courts, parked cars and Miis browsing while racers tear through.","image":"https://mario.wiki.gallery/images/thumb/9/90/MK8D_Coconut_Mall_Parking.png/320px-MK8D_Coconut_Mall_Parking.png"},{"name":"Super Star","rarity":"chase","id":"super-star","subtitle":"Item","details":"Grants a short spell of invincibility and extra speed, letting the user barge rivals aside. It first appeared in Super Mario Kart.","image":"https://mario.wiki.gallery/images/2/22/MKT_Icon_Star.png"},{"name":"Spiny Shell","rarity":"chase","id":"spiny-shell","subtitle":"Item","details":"The feared blue shell: it flies straight to the race leader and detonates on them. Nothing causes more arguments. It debuted in Mario Kart 64.","image":"https://mario.wiki.gallery/images/3/38/MKT_Icon_Spiny_Shell.png"},{"name":"Mario Kart 64","rarity":"chase","id":"mario-kart-64","subtitle":"Game","details":"Mario Kart 64 brought the series into 3D in 1996, with four-player split-screen, 16 courses and the debut of the Spiny Shell.","image":"assets/sets/compress/mkrt__mario-kart-64.webp"},{"name":"Luigi","rarity":"legendary","id":"luigi","subtitle":"Racer","details":"Mario's taller younger brother, a middleweight racer who has been on the Mario Kart grid since Super Mario Kart in 1992.","image":"assets/sets/compress/mkrt__luigi.webp"},{"name":"Donkey Kong","rarity":"legendary","id":"donkey-kong","subtitle":"Racer","details":"The tie-wearing heavyweight ape who took over the Kong slot from Donkey Kong Jr. in Mario Kart 64 back in 1996.","image":"assets/sets/compress/mkrt__donkey-kong.webp"},{"name":"Wario","rarity":"legendary","id":"wario","subtitle":"Racer","details":"Mario's greedy rival made his Mario Kart debut in Mario Kart 64 in 1996 and has been a heavyweight regular ever since.","image":"assets/sets/compress/mkrt__wario.webp"},{"name":"Waluigi","rarity":"legendary","id":"waluigi","subtitle":"Racer","details":"Wario's lanky partner in crime debuted in Double Dash!! in 2003 - and no, he was never in Super Circuit, whatever you heard.","image":"https://mario.wiki.gallery/images/d/d8/NSO_MK8D_May_2022_Week_5_-_Character_-_Waluigi_in_The_Duke.png"},{"name":"King Boo","rarity":"legendary","id":"king-boo","subtitle":"Racer","details":"The crown-wearing king of the Boos was an unlockable heavyweight in Double Dash!! in 2003, partnered with Petey Piranha.","image":"https://mario.wiki.gallery/images/thumb/a/a9/King_Boo_Artwork_MSS.png/512px-King_Boo_Artwork_MSS.png"},{"name":"Rosalina","rarity":"legendary","id":"rosalina","subtitle":"Racer","details":"The cosmic guardian from Super Mario Galaxy joined the grid as an unlockable heavyweight in Mario Kart Wii in 2008.","image":"https://mario.wiki.gallery/images/thumb/f/f8/MK8_Rosalina_Artwork.png/512px-MK8_Rosalina_Artwork.png"},{"name":"Link","rarity":"legendary","id":"link","subtitle":"Racer","details":"The hero of Hyrule crossed over from The Legend of Zelda as Mario Kart 8 DLC in 2014, racing on the Master Cycle.","image":"https://mario.wiki.gallery/images/thumb/8/8e/Mario_Kart_8_Deluxe_Art_-_Link.png/320px-Mario_Kart_8_Deluxe_Art_-_Link.png"},{"name":"Rainbow Road (SMK)","rarity":"legendary","id":"rainbow-road-smk","subtitle":"Course","details":"The original Rainbow Road from Super Mario Kart: a narrow, guardrail-free rainbow track in space, patrolled by star-shaped Thwomps.","image":"assets/sets/compress/mkrt__rainbow-road-smk.webp"},{"name":"Moo Moo Farm","rarity":"legendary","id":"moo-moo-farm","subtitle":"Course","details":"A rolling farmland course in Mario Kart 64, racing past fences and barns while Monty Moles tunnel under the dirt track.","image":"https://mario.wiki.gallery/images/1/19/MKDS_Moo_Moo_Farm_Intro.png"},{"name":"Bowser's Castle (N64)","rarity":"legendary","id":"bowsers-castle-n64","subtitle":"Course","details":"Mario Kart 64's lava fortress: stone halls, a garden of Thwomps, spiral ramps and a drawbridge stretch above molten rock.","image":"assets/sets/compress/mkrt__bowsers-castle-n64.webp"},{"name":"Baby Park","rarity":"legendary","id":"baby-park","subtitle":"Course","details":"Double Dash's tiny oval: a chaotic seven-lap loop so small the whole field is always in item range of each other.","image":"https://mario.wiki.gallery/images/8/81/BabyParkRaceStartMK8Deluxe.jpg"},{"name":"DK Mountain","rarity":"legendary","id":"dk-mountain","subtitle":"Course","details":"Double Dash's volcano run: a barrel cannon fires racers to the summit, then it's a boulder-dodging descent back down.","image":"https://mario.wiki.gallery/images/thumb/a/a6/MK8D_GCN_DK_Mountain.png/320px-MK8D_GCN_DK_Mountain.png"},{"name":"Maple Treeway","rarity":"legendary","id":"maple-treeway","subtitle":"Course","details":"An autumn treetop course in Mario Kart Wii, racing across giant maple canopies and bouncing on a net strung between the trees.","image":"https://mario.wiki.gallery/images/f/fc/MK7MapleTreewayFinalStraight.jpg"},{"name":"Rainbow Road (Wii)","rarity":"legendary","id":"rainbow-road-wii","subtitle":"Course","details":"Mario Kart Wii's Rainbow Road dives and climbs over the planet, with star-bit boosters, a half-pipe and huge airborne drops.","image":"https://mario.wiki.gallery/images/thumb/4/4e/MK8D_Wii_Rainbow_Road_Scene_8.png/320px-MK8D_Wii_Rainbow_Road_Scene_8.png"},{"name":"Mount Wario","rarity":"legendary","id":"mount-wario","subtitle":"Course","details":"A point-to-point mountain descent in Mario Kart 8: dam, forest slalom, ski jumps and a stadium finish, raced in sections.","image":"https://mario.wiki.gallery/images/thumb/2/24/Mount_Wario_MK8_Waluigi.png/320px-Mount_Wario_MK8_Waluigi.png"},{"name":"Rainbow Road (MK8)","rarity":"legendary","id":"rainbow-road-mk8","subtitle":"Course","details":"Mario Kart 8's Rainbow Road orbits a space station, racing along rainbow rails with the planet spread out far below.","image":"https://mario.wiki.gallery/images/d/d2/MK8-Course-RainbowRoad-overview.jpg"},{"name":"Big Donut","rarity":"legendary","id":"big-donut","subtitle":"Battle Course","details":"A donut-shaped battle arena in Mario Kart 64: a ring of track around a lava centre, so every fight happens on the edge.","image":"https://mario.wiki.gallery/images/f/f4/BigDonutMK7.png"},{"name":"Block Fort","rarity":"legendary","id":"block-fort","subtitle":"Battle Course","details":"Mario Kart 64's beloved block fortress: a multi-level arena of coloured block towers joined by bridges and ramps.","image":"https://mario.wiki.gallery/images/f/f2/MKDS_Block_Fort_Intro.png"},{"name":"Red Shell","rarity":"legendary","id":"red-shell","subtitle":"Item","details":"A shell that locks onto the racer ahead and hunts them down, far harder to dodge than a green one. It debuted in Super Mario Kart.","image":"https://mario.wiki.gallery/images/7/7e/MKT_Icon_Red_Shell.png"},{"name":"Lightning","rarity":"legendary","id":"lightning","subtitle":"Item","details":"A bolt that strikes every rival on the track, shrinking them, slowing them down and costing them their items. Debuted in Super Mario Kart.","image":"https://mario.wiki.gallery/images/b/b6/MKT_Icon_Lightning.png"},{"name":"Bullet Bill","rarity":"legendary","id":"bullet-bill","subtitle":"Item","details":"Transforms the kart into a Bullet Bill that rockets down the track on autopilot, knocking rivals aside. It first appeared in Mario Kart DS.","image":"https://mario.wiki.gallery/images/c/cc/MKT_Icon_Bullet_Bill.png"},{"name":"Blue Falcon","rarity":"legendary","id":"blue-falcon","subtitle":"Vehicle","details":"Captain Falcon's F-Zero machine shrunk to a kart, blue nose and all, crossing over into Mario Kart 8 as download content.","image":"https://mario.wiki.gallery/images/f/f6/MK8BlueFalcon.png"},{"name":"B Dasher","rarity":"legendary","id":"b-dasher","subtitle":"Vehicle","details":"A classic grand-prix kart that began life as Mario's signature ride in Mario Kart DS, then returned to Mario Kart 8 as download content.","image":"https://mario.wiki.gallery/images/e/e0/MKWorld_Kart_B_Dasher.png"},{"name":"Mushroom Cup","rarity":"legendary","id":"mushroom-cup","subtitle":"Cup","details":"One of the four original cups from Super Mario Kart in 1992, the Mushroom Cup is the traditional starting point of a Grand Prix.","image":"https://mario.wiki.gallery/images/1/15/MK8_MushroomCup.png"},{"name":"Special Cup","rarity":"legendary","id":"special-cup","subtitle":"Cup","details":"The final and hardest of Super Mario Kart's original four cups, the Special Cup is where Rainbow Road traditionally waits.","image":"https://mario.wiki.gallery/images/6/65/MK8_Special_Cup_Emblem.png"},{"name":"Lightning Cup","rarity":"legendary","id":"lightning-cup","subtitle":"Cup","details":"The Lightning Cup debuted as a regular cup in Super Circuit in 2001, then became the final retro cup from Mario Kart DS onward.","image":"https://mario.wiki.gallery/images/1/19/MK8_Lightning_Cup_Emblem.png"},{"name":"Super Mario Kart","rarity":"legendary","id":"super-mario-kart","subtitle":"Game","details":"The 1992 SNES original that started the series, with eight racers, Mode 7 tracks, and the first shells, bananas and Lightning.","image":"https://mario.wiki.gallery/images/thumb/8/82/Super_Mario_Kart_NA_box_art.png/320px-Super_Mario_Kart_NA_box_art.png"},{"name":"Mario Kart Wii","rarity":"legendary","id":"mario-kart-wii","subtitle":"Game","details":"Mario Kart Wii raced onto the Wii in 2008 with motion controls, motorbikes, 12-player online races and the Wii Wheel.","image":"https://mario.wiki.gallery/images/f/f5/Mario_Kart_Wii_Box_EU.jpg"},{"name":"Mario Kart World","rarity":"legendary","id":"mario-kart-world","subtitle":"Game","details":"Mario Kart World launched with the Switch 2 in 2025, connecting its courses into one open world with 24-player races.","image":"assets/sets/compress/mkrt__mario-kart-world.webp"},{"name":"Mario Kart 8 Deluxe","rarity":"legendary","id":"mario-kart-8-deluxe","subtitle":"Game","details":"Mario Kart 8 Deluxe ported the Wii U racer to Switch in 2017, then doubled its course count to 96 with the Booster Course Pass.","image":"https://mario.wiki.gallery/images/3/3d/Mario_Kart_8_Deluxe_South_Africa_box_art.jpg"},{"name":"Koopa Troopa","rarity":"epic","id":"koopa-troopa","subtitle":"Racer","details":"A lightweight foot soldier of the Koopa Troop who debuted in 1992, skipped Mario Kart 64, and returned in Double Dash!!.","image":"https://mario.wiki.gallery/images/thumb/d/dc/Koopa_Troopa_Artwork_-_Mario_Kart_Wii.png/320px-Koopa_Troopa_Artwork_-_Mario_Kart_Wii.png"},{"name":"Toad","rarity":"epic","id":"toad","subtitle":"Racer","details":"Peach's loyal mushroom retainer, a lightweight racer who has been part of the Mario Kart grid since the 1992 original.","image":"https://mario.wiki.gallery/images/thumb/e/e0/MKT_Toad_Artwork.png/320px-MKT_Toad_Artwork.png"},{"name":"Princess Daisy","rarity":"epic","id":"princess-daisy","subtitle":"Racer","details":"The tomboyish princess of Sarasaland joined the grid in Double Dash!! in 2003, as Peach's default partner with the Heart item.","image":"assets/sets/compress/mkrt__princess-daisy.webp"},{"name":"Birdo","rarity":"epic","id":"birdo","subtitle":"Racer","details":"The ribbon-wearing, egg-spitting Birdo debuted as Yoshi's default partner in Mario Kart: Double Dash!! in 2003.","image":"assets/sets/compress/mkrt__birdo.webp"},{"name":"Bowser Jr.","rarity":"epic","id":"bowser-jr","subtitle":"Racer","details":"Bowser's mischievous son and heir debuted alongside his dad in Double Dash!! in 2003, a lightweight with a big attitude.","image":"assets/sets/compress/mkrt__bowser-jr.webp"},{"name":"Funky Kong","rarity":"epic","id":"funky-kong","subtitle":"Racer","details":"The sunglasses-wearing, surf-loving Kong was an unlockable heavyweight racer in Mario Kart Wii in 2008, famed for his speed.","image":"https://vignette.wikia.nocookie.net/mariokart/images/b/b0/Funky_Kong_Artwork_-_Mario_Kart_Wii.png/revision/latest?cb=20170720230955"},{"name":"Dry Bowser","rarity":"epic","id":"dry-bowser","subtitle":"Racer","details":"The skeletal form Bowser takes after a fall in lava, Dry Bowser became his own heavyweight racer in Mario Kart Wii in 2008.","image":"https://mario.wiki.gallery/images/thumb/9/9d/Dry_Bowser_Artwork.png/512px-Dry_Bowser_Artwork.png"},{"name":"Metal Mario","rarity":"epic","id":"metal-mario","subtitle":"Racer","details":"Mario turned to solid metal became a heavyweight racer in Mario Kart 7 in 2011, far heavier than his fleshy original self.","image":"https://mario.wiki.gallery/images/thumb/3/3f/Metal_Mario_Artwork_-_Mario_Kart_7.png/320px-Metal_Mario_Artwork_-_Mario_Kart_7.png"},{"name":"Pauline","rarity":"epic","id":"pauline","subtitle":"Racer","details":"Pauline, the damsel from the original Donkey Kong arcade game, became a Mario Kart racer in Tour in 2019, fresh from New Donk City.","image":"https://mario.wiki.gallery/images/d/d6/MKWorld_Pauline.png"},{"name":"Cow","rarity":"epic","id":"cow","subtitle":"Racer","details":"One of the cows grazing at Moo Moo Meadows since 1996, Cow became Mario Kart World's breakout playable racer in 2025.","image":"assets/sets/compress/mkrt__cow.webp"},{"name":"Toad's Turnpike","rarity":"epic","id":"toads-turnpike","subtitle":"Course","details":"A night-time highway in Mario Kart 64, racing against live traffic: cars, trucks and buses share the road and none of them yield.","image":"https://vignette.wikia.nocookie.net/mariokart/images/0/0e/MK8_N64ToadsTurnpike.jpg/revision/latest?cb=20150413063929"},{"name":"Daisy Cruiser","rarity":"epic","id":"daisy-cruiser","subtitle":"Course","details":"A course set across the decks of Daisy's cruise ship in Double Dash, through the dining room, pool deck and tilting corridors.","image":"https://vignette.wikia.nocookie.net/mariokart/images/b/b3/Daisy_Cruiser_in_MK8DX.webp/revision/latest?cb=20230706195900"},{"name":"Wario Colosseum","rarity":"epic","id":"wario-colosseum","subtitle":"Course","details":"A vast steel colosseum in Double Dash, all banked bowls and corkscrew ramps — and only two laps because the lap is so long.","image":"https://vignette.wikia.nocookie.net/mariokart/images/d/d1/Wario_Colosseum_-_Big_Jump.png/revision/latest?cb=20120331000042"},{"name":"Dino Dino Jungle","rarity":"epic","id":"dino-dino-jungle","subtitle":"Course","details":"A prehistoric jungle in Double Dash with giant dinosaurs stomping beside the track, geysers and a cave of crystals.","image":"https://vignette.wikia.nocookie.net/mariokart/images/a/a1/MKDD_Dino_Forest_11.png/revision/latest?cb=20160621004155"},{"name":"Rainbow Road (GCN)","rarity":"epic","id":"rainbow-road-gcn","subtitle":"Course","details":"Double Dash's Rainbow Road spirals down a giant rainbow tube above a city, with boost rings and a huge drop at the start.","image":"https://vignette.wikia.nocookie.net/mariokart/images/6/6e/Double_Dash_Rainbow_Road.png/revision/latest?cb=20160621083258"},{"name":"Tick-Tock Clock","rarity":"epic","id":"tick-tock-clock","subtitle":"Course","details":"A course inside a giant clock in Mario Kart DS, racing across swinging pendulums, rotating gears and moving clock hands.","image":"https://vignette.wikia.nocookie.net/mariokart/images/a/ad/MK8-Course-DS_Tick-TockClock.jpg/revision/latest?cb=20150619164855"},{"name":"Airship Fortress","rarity":"epic","id":"airship-fortress","subtitle":"Course","details":"A Bowser airship assault course in Mario Kart DS, dodging Bullet Bills and Rocky Wrenches across decks and a burning tower.","image":"https://vignette.wikia.nocookie.net/mariokart/images/d/d7/640px-AirshipFortressMK7.png/revision/latest?cb=20111224180043"},{"name":"Koopa Cape","rarity":"epic","id":"koopa-cape","subtitle":"Course","details":"A cape course in Mario Kart Wii that dives underwater through a glass tube, racing alongside Cheep Cheeps and an electric eel.","image":"https://vignette.wikia.nocookie.net/mariokart/images/6/66/Koopa_Cape_Mirror_in_MK8DX.png/revision/latest?cb=20230906203236"},{"name":"Grumble Volcano","rarity":"epic","id":"grumble-volcano","subtitle":"Course","details":"A volcano course in Mario Kart Wii where the track crumbles into the lava as the race goes on, sinking section by section.","image":"https://vignette.wikia.nocookie.net/mariokart/images/0/0d/MK8-Course-Wii_GrumbleVolcano.jpg/revision/latest?cb=20150626174113"},{"name":"Bowser's Castle (Wii)","rarity":"epic","id":"bowsers-castle-wii","subtitle":"Course","details":"Mario Kart Wii's lava castle features a giant mechanical Bowser spitting fireballs across a banked, half-pipe hall.","image":"https://vignette.wikia.nocookie.net/mariokart/images/6/68/MKWii_-_Bowser%27s_Castle_%282%29.png/revision/latest?cb=20230312144517"},{"name":"Rainbow Road (3DS)","rarity":"epic","id":"rainbow-road-3ds","subtitle":"Course","details":"Mario Kart 7's Rainbow Road races over the moon's surface and through a planet's rings in one long, sectioned space flight.","image":"https://vignette.wikia.nocookie.net/mariokart/images/7/72/3DS_Rainbow_Road_Mirror_in_MK8DX.png/revision/latest?cb=20231011205454"},{"name":"Mario Kart Stadium","rarity":"epic","id":"mario-kart-stadium","subtitle":"Course","details":"Mario Kart 8's floodlit stadium opener, introducing anti-gravity racing on a banked circuit built for television spectacle.","image":"https://vignette.wikia.nocookie.net/mariokart/images/7/78/MK8D_Inkling_and_Mario_in_Mario_Kart_Stadium.png/revision/latest?cb=20200925165012"},{"name":"Electrodrome","rarity":"epic","id":"electrodrome","subtitle":"Course","details":"A neon dance-club circuit in Mario Kart 8, pulsing with laser lights and giant speakers under a starry, musical night sky.","image":"https://vignette.wikia.nocookie.net/mariokart/images/6/68/MK8-Course-Electrodrome-Mirror.png/revision/latest?cb=20230902184749"},{"name":"Bowser's Castle (MK8)","rarity":"epic","id":"bowsers-castle-mk8","subtitle":"Course","details":"Mario Kart 8's lava castle is guarded by a colossal stone Bowser that punches the track with its fists as racers pass.","image":"https://vignette.wikia.nocookie.net/mariokart/images/b/b9/Bowser%27s_Castle_%28Mario_Kart_8%29.png/revision/latest?cb=20150402154212"},{"name":"Rainbow Road (World)","rarity":"epic","id":"rainbow-road-world","subtitle":"Course","details":"Mario Kart World's Rainbow Road is the open world's grand finale, a long rainbow ascent revealed above the whole map.","image":"https://vignette.wikia.nocookie.net/mariokart/images/8/8b/1600px-MKWorld_Rainbow_Road_Lap_1.jpg/revision/latest?cb=20260129163713"},{"name":"Cookie Land","rarity":"epic","id":"cookie-land","subtitle":"Battle Course","details":"A battle arena baked like a giant cookie in Double Dash, a round, open biscuit with barriers of icing and chocolate.","image":"assets/sets/compress/mkrt__cookie-land.webp"},{"name":"Delfino Pier","rarity":"epic","id":"delfino-pier","subtitle":"Battle Course","details":"A harbour pier battle arena in Mario Kart Wii, fighting along a narrow boardwalk with the sea waiting on both sides.","image":"https://mario.wiki.gallery/images/thumb/1/11/Delfino_Pier.png/320px-Delfino_Pier.png"},{"name":"Battle Stadium","rarity":"epic","id":"battle-stadium","subtitle":"Battle Course","details":"Mario Kart 8 Deluxe's purpose-built battle stadium, a clean arena with a raised centre made for balloon battles.","image":"https://mario.wiki.gallery/images/thumb/9/9c/MK8D-BattleStadium.jpg/320px-MK8D-BattleStadium.jpg"},{"name":"Dragon Palace","rarity":"epic","id":"dragon-palace","subtitle":"Battle Course","details":"A battle arena in a Chinese palace courtyard in Mario Kart 8 Deluxe, with dragon statues watching over the fight.","image":"https://mario.wiki.gallery/images/f/fa/MK8D-DragonPalace.jpg"},{"name":"Dash Mushroom","rarity":"epic","id":"dash-mushroom","subtitle":"Item","details":"A mushroom that gives an instant burst of speed, handy for cutting across grass and shortcuts. It first appeared in Super Mario Kart.","image":"https://mario.wiki.gallery/images/6/6c/MKT_Icon_Mushroom.png"},{"name":"Green Shell","rarity":"epic","id":"green-shell","subtitle":"Item","details":"A shell fired in a straight line that ricochets off walls and knocks over any racer it hits. It first appeared in Super Mario Kart.","image":"https://mario.wiki.gallery/images/9/96/MKT_Icon_Green_Shell.png"},{"name":"Banana","rarity":"epic","id":"banana","subtitle":"Item","details":"A peel dropped onto the track as a slippery trap; whoever runs over it spins out. The humble hazard has been around since Super Mario Kart.","image":"https://mario.wiki.gallery/images/1/11/MKT_Icon_Banana.png"},{"name":"Bob-omb","rarity":"epic","id":"bob-omb","subtitle":"Item","details":"A wind-up bomb that can be thrown ahead or dropped behind, exploding in a blast that flips nearby racers. It first appeared in Double Dash!!.","image":"https://mario.wiki.gallery/images/d/d1/MKT_Icon_Bob-omb.png"},{"name":"Super Horn","rarity":"epic","id":"super-horn","subtitle":"Item","details":"Lets out a blast that shatters nearby shells and items — even a Spiny Shell — and rocks racers close by. It first appeared in Mario Kart 8.","image":"https://mario.wiki.gallery/images/4/48/MKT_Icon_Super_Horn.png"},{"name":"Standard Kart","rarity":"epic","id":"standard-kart","subtitle":"Vehicle","details":"The default all-round kart body of Mario Kart 8: a red and white open-top racer with no extremes, the yardstick every other body is measured against.","image":"assets/sets/compress/mkrt__standard-kart.webp"},{"name":"Mach 8","rarity":"epic","id":"mach-8","subtitle":"Vehicle","details":"A sleek grand-prix style kart with a pointed nose and open wheels, one of Mario Kart 8's sportiest bodies. Its name is a play on speed itself.","image":"https://mario.wiki.gallery/images/c/c6/SSBU_Mach_8_Spirit.png"},{"name":"Cat Cruiser","rarity":"epic","id":"cat-cruiser","subtitle":"Vehicle","details":"A kart with cat ears, tail and whiskered face, made to match Cat Peach's suit. The Cat Cruiser first raced in Mario Kart 8.","image":"https://mario.wiki.gallery/images/f/f4/CatCruiserBodyMK8.png"},{"name":"Gold Standard","rarity":"epic","id":"gold-standard","subtitle":"Vehicle","details":"The Standard Kart recast in solid gold, Mario Kart 8's gleaming prize body for drivers who have earned their shine on the track.","image":"https://mario.wiki.gallery/images/5/5d/GoldStandard-Wario-MK8.jpg"},{"name":"Barrel Train","rarity":"epic","id":"barrel-train","subtitle":"Vehicle","details":"Donkey Kong and Diddy Kong's locomotive kart from Double Dash!!, a little steam train with a barrel for a boiler and a whistle to match.","image":"https://mario.wiki.gallery/images/4/4c/MK7_Barrel_Train.png"},{"name":"Flower Cup","rarity":"epic","id":"flower-cup","subtitle":"Cup","details":"One of Super Mario Kart's original four cups from 1992, the Flower Cup is traditionally the second step up in a Grand Prix.","image":"https://mario.wiki.gallery/images/a/a8/MK8_FlowerCup.png"},{"name":"Star Cup","rarity":"epic","id":"star-cup","subtitle":"Cup","details":"One of the original four cups from Super Mario Kart in 1992, the Star Cup traditionally holds a game's trickier courses.","image":"https://mario.wiki.gallery/images/7/78/MK8_Star_Cup_Emblem.png"},{"name":"Shell Cup","rarity":"epic","id":"shell-cup","subtitle":"Cup","details":"The Shell Cup debuted in Mario Kart DS in 2005 as the gentlest of the retro cups, bringing back four courses from older games.","image":"https://mario.wiki.gallery/images/c/cc/MK8_Shell_Cup_Emblem.png"},{"name":"Spiny Cup","rarity":"epic","id":"spiny-cup","subtitle":"Cup","details":"The final Booster Course Pass cup, the Spiny Cup closed out Wave 6 in 2023 - a cup named for the dreaded blue shell itself.","image":"https://mario.wiki.gallery/images/1/10/MK8D_BCP_Spiny_Emblem.png"},{"name":"Mario Kart: Super Circuit","rarity":"epic","id":"mario-kart-super-circuit","subtitle":"Game","details":"Mario Kart: Super Circuit put the series on the Game Boy Advance in 2001, with 20 new courses plus all 20 SNES courses as extras.","image":"assets/sets/compress/mkrt__mario-kart-super-circuit.webp"},{"name":"Mario Kart: Double Dash!!","rarity":"epic","id":"mario-kart-double-dash","subtitle":"Game","details":"Double Dash!! put two racers in every kart on the GameCube in 2003, swapping drivers mid-race and giving pairs special items.","image":"https://mario.wiki.gallery/images/7/70/Mario_Kart_Double_Dash%21%21.jpg"},{"name":"Mario Kart DS","rarity":"epic","id":"mario-kart-ds","subtitle":"Game","details":"Mario Kart DS took the series online in 2005 and added Retro Grand Prix, missions, and R.O.B. as a surprise unlockable racer.","image":"https://mario.wiki.gallery/images/e/e7/Mario_Kart_DS_Box_NA_Rerelease.jpg"},{"name":"Mario Kart 7","rarity":"epic","id":"mario-kart-7","subtitle":"Game","details":"Mario Kart 7 took the series into stereoscopic 3D on the 3DS in 2011, adding gliders and underwater driving to its races.","image":"https://mario.wiki.gallery/images/5/5e/Mario-Kart-7-Box-Art.jpg"},{"name":"Mario Kart 8","rarity":"epic","id":"mario-kart-8","subtitle":"Game","details":"Mario Kart 8 flipped racing onto walls and ceilings with anti-gravity on the Wii U in 2014, and added the race-saving Super Horn.","image":"assets/sets/compress/mkrt__mario-kart-8.webp"},{"name":"Baby Mario","rarity":"rare","id":"baby-mario","subtitle":"Racer","details":"The first of the baby racers, Baby Mario time-travelled into the series in Double Dash!! in 2003 as a lightweight.","image":"https://mario.wiki.gallery/images/thumb/6/64/MK8_Baby_Mario_Artwork.png/320px-MK8_Baby_Mario_Artwork.png"},{"name":"Baby Luigi","rarity":"rare","id":"baby-luigi","subtitle":"Racer","details":"Baby Luigi joined his brother's baby self in Double Dash!! in 2003, the pair sharing the Chain Chomp as their special item.","image":"assets/sets/compress/mkrt__baby-luigi.webp"},{"name":"Toadette","rarity":"rare","id":"toadette","subtitle":"Racer","details":"Toadette made her debut in any game as Toad's unlockable partner in Double Dash!! in 2003, racing in pink from the start.","image":"assets/sets/compress/mkrt__toadette.webp"},{"name":"Diddy Kong","rarity":"rare","id":"diddy-kong","subtitle":"Racer","details":"Donkey Kong's nimble sidekick joined the series in Double Dash!! in 2003, partnering DK and sharing the Giant Banana.","image":"https://mario.wiki.gallery/images/thumb/1/11/MK8D_Diddy_Kong.png/320px-MK8D_Diddy_Kong.png"},{"name":"Petey Piranha","rarity":"rare","id":"petey-piranha","subtitle":"Racer","details":"The giant mutant Piranha Plant was an unlockable heavyweight in Double Dash!! in 2003, partnered with King Boo.","image":"https://mario.wiki.gallery/images/6/61/MK8D_PeteyPiranha_WildWoods.jpg"},{"name":"R.O.B.","rarity":"rare","id":"r-o-b","subtitle":"Racer","details":"Nintendo's 1985 robot accessory became a heavyweight racer in Mario Kart DS in 2005 - still his only Mario Kart appearance.","image":"https://mario.wiki.gallery/images/thumb/b/b6/MKDS_ROB_Artwork.png/320px-MKDS_ROB_Artwork.png"},{"name":"Roy Koopa","rarity":"rare","id":"roy-koopa","subtitle":"Racer","details":"Roy Koopa, the shades-wearing bully of the Koopalings, is a heavyweight who joined the series in Mario Kart 8 in 2014.","image":"https://mario.wiki.gallery/images/a/ab/Roy_Koopa_MK8.png"},{"name":"Ludwig von Koopa","rarity":"rare","id":"ludwig-von-koopa","subtitle":"Racer","details":"Ludwig von Koopa, the eldest and most pompous of the seven Koopalings, became a middleweight racer in Mario Kart 8 in 2014.","image":"https://vignette.wikia.nocookie.net/mariokart/images/6/6d/Ludwig_Von_Koopa_MK8.png/revision/latest?cb=20140521151048"},{"name":"Villager","rarity":"rare","id":"villager","subtitle":"Racer","details":"The mayor of Animal Crossing crossed over as Mario Kart 8 DLC in 2014; boy and girl Villagers are separate slots in Deluxe.","image":"https://mario.wiki.gallery/images/7/70/Villager_MK8.png"},{"name":"Isabelle","rarity":"rare","id":"isabelle","subtitle":"Racer","details":"Animal Crossing's ever-helpful secretary Isabelle joined the grid in Mario Kart 8's second DLC pack, released in 2015.","image":"https://mario.wiki.gallery/images/1/12/Isabelle_MK8.png"},{"name":"Inkling","rarity":"rare","id":"inkling","subtitle":"Racer","details":"The squid kids of Splatoon inked their way into Mario Kart 8 Deluxe in 2017, with Inkling Girl and Boy as separate slots.","image":"https://mario.wiki.gallery/images/thumb/b/bb/MK8_Deluxe_Art_-_Inkling.png/320px-MK8_Deluxe_Art_-_Inkling.png"},{"name":"Kamek","rarity":"rare","id":"kamek","subtitle":"Racer","details":"Bowser's Magikoopa advisor Kamek was cut from Mario Kart 64, and finally became a playable racer in Mario Kart Tour in 2019.","image":"https://mario.wiki.gallery/images/thumb/3/3c/SMPJ_Kamek_Artwork.png/512px-SMPJ_Kamek_Artwork.png"},{"name":"Goomba","rarity":"rare","id":"goomba","subtitle":"Racer","details":"The Goomba, the very first enemy Mario ever stomped back in 1985, finally became a playable racer in Mario Kart World in 2025.","image":"https://mario.wiki.gallery/images/3/3a/MKT_Goomba.png"},{"name":"Luigi Raceway","rarity":"rare","id":"luigi-raceway","subtitle":"Course","details":"Mario Kart 64's gentle opener: a wide, banked Luigi-themed speedway with a tunnel, a hot-air balloon and room to learn the ropes.","image":"https://vignette.wikia.nocookie.net/mariokart/images/c/c6/Luigi_Raceway.png/revision/latest?cb=20120317172847"},{"name":"Choco Mountain","rarity":"rare","id":"choco-mountain","subtitle":"Course","details":"A mountain pass in Mario Kart 64 with chocolate-brown slopes, a cave tunnel and boulders that roll down across the track.","image":"https://vignette.wikia.nocookie.net/mariokart/images/0/0a/Choco_Mountain_%28MK8DX%29.jpg/revision/latest?cb=20220211011134"},{"name":"Mario Raceway","rarity":"rare","id":"mario-raceway","subtitle":"Course","details":"Mario's Mario Kart 64 home circuit: a clean paved course past a giant Mario statue, with a pipe tunnel and wide, flowing corners.","image":"https://vignette.wikia.nocookie.net/mariokart/images/9/99/MKWii_Mario_Raceway_Mirror.png/revision/latest?cb=20230906232153"},{"name":"Sherbet Land (N64)","rarity":"rare","id":"sherbet-land-n64","subtitle":"Course","details":"An icy cavern course in Mario Kart 64 where penguins waddle across frozen lakes and the cave section is polished, slippery ice.","image":"https://vignette.wikia.nocookie.net/mariokart/images/3/3c/029.jpg/revision/latest?cb=20080801141300"},{"name":"Royal Raceway","rarity":"rare","id":"royal-raceway","subtitle":"Course","details":"A grand paved circuit in Mario Kart 64 running past Peach's Castle, with a lake jump, wide straights and a royal grandstand finish.","image":"https://vignette.wikia.nocookie.net/mariokart/images/3/39/MK8_Royal_Raceway_Peach_Blowkiss.png/revision/latest?cb=20141024065234"},{"name":"DK's Jungle Parkway","rarity":"rare","id":"dks-jungle-parkway","subtitle":"Course","details":"A jungle river course in Mario Kart 64, leaping a paddle steamer on the big jump and racing through dense, misty rainforest.","image":"https://vignette.wikia.nocookie.net/mariokart/images/b/b0/DK%27s_jungle_parkway_.png/revision/latest?cb=20130823235602"},{"name":"Yoshi Valley","rarity":"rare","id":"yoshi-valley","subtitle":"Course","details":"A maze-like canyon in Mario Kart 64 with several splitting routes, no reliable positions mid-race, and a giant egg at the end.","image":"https://vignette.wikia.nocookie.net/mariokart/images/4/43/MK8-Course-N64_YoshiValley.png/revision/latest?cb=20150616175706"},{"name":"Banshee Boardwalk","rarity":"rare","id":"banshee-boardwalk","subtitle":"Course","details":"A creaking haunted pier in Mario Kart 64, winding over dark water with Cheep Cheeps leaping through gaps in the boards.","image":"https://vignette.wikia.nocookie.net/mariokart/images/9/9c/Banshee_boardwalk.jpg/revision/latest?cb=20130824174805"},{"name":"Peach Beach","rarity":"rare","id":"peach-beach","subtitle":"Course","details":"A beach resort course in Double Dash beside a cruise ship, where the tide and shallow water shape the racing line past Cataquacks.","image":"https://vignette.wikia.nocookie.net/mariokart/images/7/75/Peach_Beach_Overview_-_Mario_Kart_Wii.png/revision/latest?cb=20120317174615"},{"name":"Mushroom City","rarity":"rare","id":"mushroom-city","subtitle":"Course","details":"A neon city course in Double Dash raced at night, weaving between skyscrapers, traffic and a maze of side streets.","image":"https://vignette.wikia.nocookie.net/mariokart/images/1/18/MKDD_Mushroom_City_02.png/revision/latest?cb=20170703071850"},{"name":"Yoshi Circuit","rarity":"rare","id":"yoshi-circuit","subtitle":"Course","details":"A circuit shaped like Yoshi himself in Double Dash, curling around the island with a tunnel through the egg-shaped middle.","image":"https://vignette.wikia.nocookie.net/mariokart/images/b/b8/Mk8-dlc-yoshi-circuit-1-.jpg/revision/latest?cb=20150211200424"},{"name":"Delfino Square","rarity":"rare","id":"delfino-square","subtitle":"Course","details":"A harbour town course from Mario Kart DS, racing through Delfino Plaza's streets, over its bridge and down steps to the pier.","image":"https://vignette.wikia.nocookie.net/mariokart/images/9/9e/Defino_Square_in_MKWii.jpg/revision/latest?cb=20221203214226"},{"name":"Shroom Ridge","rarity":"rare","id":"shroom-ridge","subtitle":"Course","details":"A cliff-edge ridge road in Mario Kart DS with heavy traffic, tight bends and long drops waiting on either side of the tarmac.","image":"https://vignette.wikia.nocookie.net/mariokart/images/c/ca/Shroom_Ridge_%28MK8DX%29.jpg/revision/latest?cb=20220210225308"},{"name":"Moo Moo Meadows","rarity":"rare","id":"moo-moo-meadows","subtitle":"Course","details":"A gentle pasture course in Mario Kart Wii, racing between grazing cows that wander the track under a big, bright sky.","image":"https://vignette.wikia.nocookie.net/mariokart/images/f/f3/800px-MKWii-MooMooMeadows1.png/revision/latest?cb=20150406101410"},{"name":"Mushroom Gorge","rarity":"rare","id":"mushroom-gorge","subtitle":"Course","details":"A gorge course in Mario Kart Wii where giant mushrooms are trampolines, bouncing racers across deep drops between cliffs.","image":"https://vignette.wikia.nocookie.net/mariokart/images/6/67/Mushroom_Gorge_in_MK8DX_img1.jpg/revision/latest?cb=20220916040212"},{"name":"DK Summit","rarity":"rare","id":"dk-summit","subtitle":"Course","details":"A snowboard-cross style descent in Mario Kart Wii, launched from a barrel cannon to a half-pipe course of Shy Guy snowboarders.","image":"https://vignette.wikia.nocookie.net/mariokart/images/f/f0/DK_Summit_Mirror_in_MK8DX.png/revision/latest?cb=20230911203913"},{"name":"Wario's Gold Mine","rarity":"rare","id":"warios-gold-mine","subtitle":"Course","details":"A mine course in Mario Kart Wii racing on rails and planks around Wario's gold works, dodging mine carts and Swoops.","image":"https://vignette.wikia.nocookie.net/mariokart/images/2/29/MK8-DLC-Course-Wii_Wario%27sGoldMine-screenshot-MetalMario.jpg/revision/latest?cb=20150819051440"},{"name":"Dry Dry Ruins","rarity":"rare","id":"dry-dry-ruins","subtitle":"Course","details":"Ancient desert ruins in Mario Kart Wii, with a temple interior of pillars and traps beyond the Pokey-patrolled dunes outside.","image":"https://vignette.wikia.nocookie.net/mariokart/images/3/31/1074350-drydry_ruinsd.jpg/revision/latest?cb=20100207185525"},{"name":"Moonview Highway","rarity":"rare","id":"moonview-highway","subtitle":"Course","details":"A night highway in Mario Kart Wii raced against traffic under a full moon, with toll booths and a city skyline at the end.","image":"https://vignette.wikia.nocookie.net/mariokart/images/1/12/Moonview_Highway_Mirror_in_MK8DX.png/revision/latest?cb=20230902140421"},{"name":"DK Jungle","rarity":"rare","id":"dk-jungle","subtitle":"Course","details":"A jungle course in Mario Kart 7 past DK's house and a golden temple, gliding over the canopy in Donkey Kong Country style.","image":"https://vignette.wikia.nocookie.net/mariokart/images/e/ec/MK8DX_-_3DS_DK_Jungle.png/revision/latest?cb=20230312161009"},{"name":"Rosalina's Ice World","rarity":"rare","id":"rosalinas-ice-world","subtitle":"Course","details":"An icy course in Mario Kart 7 sliding through frozen caves and underwater ice tunnels beneath a starry, polar sky.","image":"https://vignette.wikia.nocookie.net/mariokart/images/2/2d/Rosalina_Ice_world.png/revision/latest?cb=20120409023734"},{"name":"Sunshine Airport","rarity":"rare","id":"sunshine-airport","subtitle":"Course","details":"A working airport in Mario Kart 8, racing through the terminal, under parked jets and along the runway as planes take off.","image":"https://vignette.wikia.nocookie.net/mariokart/images/4/43/MK8_SunshineAirportCourse.jpg/revision/latest?cb=20150401143117"},{"name":"Cloudtop Cruise","rarity":"rare","id":"cloudtop-cruise","subtitle":"Course","details":"A course in the clouds in Mario Kart 8, racing over airship decks and giant beanstalks through the edge of a thunderstorm.","image":"https://vignette.wikia.nocookie.net/mariokart/images/d/d3/MK8_Rosalina_Cloudtop_Cruise.png/revision/latest?cb=20200925061631"},{"name":"Super Bell Subway","rarity":"rare","id":"super-bell-subway","subtitle":"Course","details":"A subway course in Mario Kart 8 racing through stations and tunnels, dodging trains on the underground tracks.","image":"https://vignette.wikia.nocookie.net/mariokart/images/7/7b/MK8-DLC-Course-SuperBellSubway.jpg/revision/latest/scale-to-width-down/512"},{"name":"Big Blue","rarity":"rare","id":"big-blue","subtitle":"Course","details":"An F-Zero course in Mario Kart 8 raced in sections down a huge watercourse, ending on the ocean floor's final straight.","image":"https://vignette.wikia.nocookie.net/mariokart/images/e/e0/MK8-DLC-Course-BigBlue-overview.jpg/revision/latest/scale-to-width-down/512"},{"name":"Double Deck","rarity":"rare","id":"double-deck","subtitle":"Battle Course","details":"A two-storey battle arena in Mario Kart 64, its stacked decks linked by ramps for ambushes from the level above.","image":"https://mario.wiki.gallery/images/0/07/MK64_DoubleDeck.png"},{"name":"Skyscraper","rarity":"rare","id":"skyscraper","subtitle":"Battle Course","details":"A battle arena atop a Mario Kart 64 skyscraper, a small rooftop platform where one bad bump can send a kart over the side.","image":"assets/sets/compress/mkrt__skyscraper.webp"},{"name":"Pipe Plaza","rarity":"rare","id":"pipe-plaza","subtitle":"Battle Course","details":"A battle arena in Double Dash where green pipes warp racers between separate areas, keeping every fight unpredictable.","image":"https://mario.wiki.gallery/images/d/de/Pipe_Plaza.png"},{"name":"Luigi's Mansion (GCN)","rarity":"rare","id":"luigis-mansion-gcn","subtitle":"Battle Course","details":"A battle arena at Luigi's haunted mansion in Double Dash, fighting across the courtyard and floors of the spooky house.","image":"assets/sets/compress/mkrt__luigis-mansion-gcn.webp"},{"name":"Chain Chomp Wheel","rarity":"rare","id":"chain-chomp-wheel","subtitle":"Battle Course","details":"A circular battle arena in Mario Kart Wii built around a rotating wheel, with a Chain Chomp guarding the middle.","image":"https://mario.wiki.gallery/images/thumb/d/d3/Chain_Chomp_Roulette.png/320px-Chain_Chomp_Roulette.png"},{"name":"Thwomp Desert","rarity":"rare","id":"thwomp-desert","subtitle":"Battle Course","details":"A desert crater battle arena in Mario Kart Wii, where Thwomps slam down around the rim and edges of the sandy bowl.","image":"https://mario.wiki.gallery/images/thumb/9/9a/Thwomp_Desert.png/320px-Thwomp_Desert.png"},{"name":"Boo","rarity":"rare","id":"boo","subtitle":"Item","details":"A ghost that steals an item from a rival while turning its user invisible and hard to hit. The Boo item first appeared in Super Mario Kart.","image":"https://mario.wiki.gallery/images/thumb/a/a0/Boo_Artwork_-_Mario_Party_Island_Tour.png/512px-Boo_Artwork_-_Mario_Party_Island_Tour.png"},{"name":"Golden Mushroom","rarity":"rare","id":"golden-mushroom","subtitle":"Item","details":"A sparkling mushroom that can be used again and again for repeated speed boosts over a few seconds. It first appeared in Mario Kart 64.","image":"assets/sets/compress/mkrt__golden-mushroom.webp"},{"name":"Fake Item Box","rarity":"rare","id":"fake-item-box","subtitle":"Item","details":"A trap disguised as a genuine item box, right down to the question mark, that zaps racers who drive into it. It debuted in Mario Kart 64.","image":"https://mario.wiki.gallery/images/6/6b/MKDD_Fake_Item_Box.png"},{"name":"Blooper","rarity":"rare","id":"blooper","subtitle":"Item","details":"A squid that squirts ink across every rival's view, making the road ahead hard to read for a few seconds. It first appeared in Mario Kart DS.","image":"https://mario.wiki.gallery/images/d/de/MKT_Icon_Blooper.png"},{"name":"Mega Mushroom","rarity":"rare","id":"mega-mushroom","subtitle":"Item","details":"Supersizes the driver for a short spell, letting the giant kart squash flat any racer it drives over. It first appeared in Mario Kart Wii.","image":"https://mario.wiki.gallery/images/c/ca/MKT_Icon_Mega_Mushroom.png"},{"name":"Fire Flower","rarity":"rare","id":"fire-flower","subtitle":"Item","details":"Lets the driver throw a volley of bouncing fireballs down the track for a short time. The Fire Flower joined the item roster in Mario Kart 7.","image":"https://mario.wiki.gallery/images/0/08/MKT_Icon_Fire_Flower.png"},{"name":"Crazy Eight","rarity":"rare","id":"crazy-eight","subtitle":"Item","details":"Mario Kart 8's answer to the Lucky Seven: eight different items circle the kart at once, ready to use one after another.","image":"https://mario.wiki.gallery/images/b/b1/MK8_Deluxe_Art_-_Crazy_Eight_%28transparent%29.png"},{"name":"Pipe Frame","rarity":"rare","id":"pipe-frame","subtitle":"Vehicle","details":"A kart built from exposed green pipework, its bare frame a nod to the earliest kart designs. It races as a lightweight body in Mario Kart 8.","image":"https://mario.wiki.gallery/images/2/2f/MKWorld_Kart_Pipe_Frame_Yellow.png"},{"name":"Circuit Special","rarity":"rare","id":"circuit-special","subtitle":"Vehicle","details":"A professional-looking circuit racer with a low body and rear wing, built in the image of real track cars. It appears in Mario Kart 8.","image":"https://mario.wiki.gallery/images/d/da/MK8_Orange_Circuit_Special.png"},{"name":"Sports Coupe","rarity":"rare","id":"sports-coupe","subtitle":"Vehicle","details":"A luxury sports coupe turned kart, all smooth curves and enclosed bodywork, unlike the open karts around it. It appears in Mario Kart 8.","image":"https://mario.wiki.gallery/images/f/f8/SportsCoupeMK8.png"},{"name":"Koopa Clown","rarity":"rare","id":"koopa-clown","subtitle":"Vehicle","details":"A kart built from the Koopa Clown Car, Bowser Jr.'s grinning flying bowl, grounded and given wheels. It joined the bodies in Mario Kart 8 Deluxe.","image":"https://mario.wiki.gallery/images/5/58/MK7_Koopa_Clown.png"},{"name":"Master Cycle","rarity":"rare","id":"master-cycle","subtitle":"Vehicle","details":"Link's Hylian motorcycle, dressed in blue and gold with Triforce touches, added to Mario Kart 8 as Zelda download content.","image":"https://mario.wiki.gallery/images/8/8a/MK8MasterCycle.png"},{"name":"Wild Wiggler","rarity":"rare","id":"wild-wiggler","subtitle":"Vehicle","details":"An ATV built from a Wiggler, its long caterpillar body segmented over four wheels. The Wild Wiggler first appeared in Mario Kart 8.","image":"https://mario.wiki.gallery/images/a/aa/WildWigglerBodyMK8.png"},{"name":"Parade Kart","rarity":"rare","id":"parade-kart","subtitle":"Vehicle","details":"Double Dash!!'s golden parade kart, a prize body that any weight class can drive, earned by conquering the game's toughest cups.","image":"https://mario.wiki.gallery/images/6/6c/MKDD_Parade_Kart.png"},{"name":"Mach Bike","rarity":"rare","id":"mach-bike","subtitle":"Vehicle","details":"A sleek medium sport bike from Mario Kart Wii, in the inward-drifting class that made Wii's bikes famous on the time trial charts.","image":"https://mario.wiki.gallery/images/9/9e/Mach_Bike_%28Luigi%29_Model.png"},{"name":"Flame Runner","rarity":"rare","id":"flame-runner","subtitle":"Vehicle","details":"A large sport bike from Mario Kart Wii wearing flame livery, the heavyweight entry in the game's inward-drifting bike class.","image":"https://mario.wiki.gallery/images/a/aa/Flame_Runner_%28Rosalina%29_Model.png"},{"name":"Banana Cup","rarity":"rare","id":"banana-cup","subtitle":"Cup","details":"The Banana Cup debuted in Mario Kart DS in 2005 as a retro cup, sitting second in the retro set between Shell and Leaf.","image":"https://mario.wiki.gallery/images/7/76/MK8_Banana_Cup_Emblem.png"},{"name":"Leaf Cup","rarity":"rare","id":"leaf-cup","subtitle":"Cup","details":"The Leaf Cup debuted in Mario Kart DS in 2005 as a retro cup, third in difficulty among the four retro cups of its era.","image":"https://mario.wiki.gallery/images/2/28/MK8_Leaf_Cup_Emblem.png"},{"name":"Egg Cup","rarity":"rare","id":"egg-cup","subtitle":"Cup","details":"The Egg Cup arrived in Mario Kart 8's first DLC pack in 2014, mixing new courses like Excitebike Arena with returning ones.","image":"https://mario.wiki.gallery/images/e/ea/MK8_Egg_Cup_Emblem.png"},{"name":"Triforce Cup","rarity":"rare","id":"triforce-cup","subtitle":"Cup","details":"The Zelda-themed Triforce Cup arrived in Mario Kart 8's first DLC pack in 2014, headlined by Hyrule Circuit and Ice Ice Outpost.","image":"https://mario.wiki.gallery/images/6/6b/MK8_Triforce_Cup_Emblem.png"},{"name":"Crossing Cup","rarity":"rare","id":"crossing-cup","subtitle":"Cup","details":"The Animal Crossing-themed Crossing Cup arrived in Mario Kart 8's second DLC pack in 2015, with a course that changes season.","image":"https://mario.wiki.gallery/images/9/92/MK8_Crossing_Cup_Emblem.png"},{"name":"Bell Cup","rarity":"rare","id":"bell-cup","subtitle":"Cup","details":"The Bell Cup arrived in Mario Kart 8's second DLC pack in 2015, headlined by the anti-gravity F-Zero finale, Big Blue.","image":"https://mario.wiki.gallery/images/8/82/MK8_Bell_Cup_Emblem.png"},{"name":"Mario Kart Tour","rarity":"rare","id":"mario-kart-tour","subtitle":"Game","details":"Mario Kart Tour brought the series to phones in 2019, with one-finger steering and courses based on real-world cities.","image":"https://mario.wiki.gallery/images/2/23/Mario_Kart_Tour_Play_Nintendo_thumbnail.jpg"},{"name":"Mario Kart Arcade GP","rarity":"rare","id":"mario-kart-arcade-gp","subtitle":"Game","details":"Mario Kart Arcade GP took the series into arcades in 2005, co-developed with Namco and starring Pac-Man as a guest racer.","image":"https://mario.wiki.gallery/images/3/30/MKAGP_cabinet.jpg"},{"name":"Mario Kart Arcade GP DX","rarity":"rare","id":"mario-kart-arcade-gp-dx","subtitle":"Game","details":"Mario Kart Arcade GP DX updated the arcade series in 2013, adding Don-chan from Taiko no Tatsujin as a guest racer.","image":"https://mario.wiki.gallery/images/8/86/MKAGPDX_logo.png"},{"name":"Mario Kart Live: Home Circuit","rarity":"rare","id":"mario-kart-live-home-circuit","subtitle":"Game","details":"Mario Kart Live: Home Circuit raced a real camera-equipped RC kart around your living room in 2020, with courses on the Switch.","image":"https://mario.wiki.gallery/images/5/5c/MKLHC_MarioKart_BoxKart.png"},{"name":"Donkey Kong Jr.","rarity":"uncommon","id":"donkey-kong-jr","subtitle":"Racer","details":"A heavyweight in the 1992 original, Donkey Kong Jr. then sat out the series for decades before returning in Mario Kart Tour.","image":"https://mario.wiki.gallery/images/9/9a/Donkey_Kong_JR_SMK_artwork.jpg"},{"name":"Dry Bones","rarity":"uncommon","id":"dry-bones","subtitle":"Racer","details":"The skeletal Koopa who crumbles apart and pulls himself back together debuted as a lightweight racer in Mario Kart DS in 2005.","image":"https://vignette.wikia.nocookie.net/mariokart/images/e/ea/Dry_Bones_Artwork_-_Mario_Kart_DS.png/revision/latest?cb=20161121183728"},{"name":"Shy Guy","rarity":"uncommon","id":"shy-guy","subtitle":"Racer","details":"The masked, mumbling Shy Guy was a Download Play-only racer in Mario Kart DS in 2005, earning a full roster slot in Mario Kart 7.","image":"https://vignette.wikia.nocookie.net/mariokart/images/7/7a/Shy_Guy_-_Mario_Kart_X.png/revision/latest?cb=20200504160737"},{"name":"Baby Peach","rarity":"uncommon","id":"baby-peach","subtitle":"Racer","details":"The baby form of Princess Peach debuted in Mario Kart Wii in 2008, a lightweight counterpart to the grown-up princess.","image":"assets/sets/compress/mkrt__baby-peach.webp"},{"name":"Baby Daisy","rarity":"uncommon","id":"baby-daisy","subtitle":"Racer","details":"Baby Daisy was created brand new for Mario Kart Wii in 2008 - unlike the other babies, she had never appeared as an infant before.","image":"https://mario.wiki.gallery/images/d/d7/MKWorld_Baby_Daisy.png"},{"name":"Baby Rosalina","rarity":"uncommon","id":"baby-rosalina","subtitle":"Racer","details":"Baby Rosalina was created for Mario Kart 8 in 2014, a starry lightweight baby counterpart to the cosmic Rosalina.","image":"https://mario.wiki.gallery/images/3/33/MKT_Artwork_BabyRosalina.png"},{"name":"Pink Gold Peach","rarity":"uncommon","id":"pink-gold-peach","subtitle":"Racer","details":"Peach rendered in pink gold became a heavyweight racer in Mario Kart 8 in 2014, the metallic counterpart to Metal Mario.","image":"https://mario.wiki.gallery/images/0/01/MKT_Artwork_PinkGoldPeach.png"},{"name":"Iggy Koopa","rarity":"uncommon","id":"iggy-koopa","subtitle":"Racer","details":"Iggy Koopa, the wild-haired, giggling Koopaling, raced into the series with all six of his siblings in Mario Kart 8 in 2014.","image":"https://mario.wiki.gallery/images/0/0c/Iggy_Koopa_MK8.png"},{"name":"Lemmy Koopa","rarity":"uncommon","id":"lemmy-koopa","subtitle":"Racer","details":"Lemmy Koopa, the smallest and lightest of the seven Koopalings, brought his rainbow mohawk to the grid in Mario Kart 8.","image":"https://mario.wiki.gallery/images/6/6d/Lemmy_Koopa_MK8.png"},{"name":"Larry Koopa","rarity":"uncommon","id":"larry-koopa","subtitle":"Racer","details":"Larry Koopa, often the first Koopaling boss Mario ever fought, became a lightweight racer in Mario Kart 8 in 2014.","image":"https://mario.wiki.gallery/images/3/37/Larry_Koopa_MK8.png"},{"name":"Wendy O. Koopa","rarity":"uncommon","id":"wendy-o-koopa","subtitle":"Racer","details":"Wendy O. Koopa, the only female Koopaling, races with her bow and bangles as a lightweight in Mario Kart 8 from 2014.","image":"https://mario.wiki.gallery/images/thumb/6/67/Wendy_Koopa_MK8.png/320px-Wendy_Koopa_MK8.png"},{"name":"Morton Koopa Jr.","rarity":"uncommon","id":"morton-koopa-jr","subtitle":"Racer","details":"Morton Koopa Jr., the biggest and heaviest of the seven Koopalings, joined the Mario Kart grid in Mario Kart 8 in 2014.","image":"assets/sets/compress/mkrt__morton-koopa-jr.webp"},{"name":"Tanooki Mario","rarity":"uncommon","id":"tanooki-mario","subtitle":"Racer","details":"Mario in the leaf-powered Tanooki Suit got his own separate roster slot as Mario Kart 8 DLC in 2014, ears, tail and all.","image":"https://mario.wiki.gallery/images/thumb/a/af/Tanooki_Mario_Artwork_-_Super_Mario_3D_World.png/320px-Tanooki_Mario_Artwork_-_Super_Mario_3D_World.png"},{"name":"Cat Peach","rarity":"uncommon","id":"cat-peach","subtitle":"Racer","details":"Peach in the bell-powered Cat Suit got her own separate roster slot as Mario Kart 8 DLC in 2014, claws included.","image":"https://vignette.wikia.nocookie.net/mariokart/images/1/13/Cat_Princess_Peach_Artwork_-_Super_Mario_3D_World.png/revision/latest/scale-to-width-down/512"},{"name":"Gold Mario","rarity":"uncommon","id":"gold-mario","subtitle":"Racer","details":"Gold Mario is Mario Kart 8 Deluxe's only unlockable racer, a gleaming gold version of Metal Mario earned through Grand Prix.","image":"https://mario.wiki.gallery/images/e/ea/MKT_Artwork_GoldMario.png"},{"name":"Peachette","rarity":"uncommon","id":"peachette","subtitle":"Racer","details":"Toadette transformed by the Super Crown became Peachette, debuting in Mario Kart Tour in 2019 and later joining 8 Deluxe.","image":"https://mario.wiki.gallery/images/thumb/8/8e/MK8D_Peachette.png/320px-MK8D_Peachette.png"},{"name":"Hammer Bro","rarity":"uncommon","id":"hammer-bro","subtitle":"Racer","details":"The helmeted, hammer-throwing Hammer Bro became a racer in Mario Kart Tour in 2019, later racing on console in World.","image":"https://mario.wiki.gallery/images/4/41/Mario_Kart_World_Hammer_Bro.png"},{"name":"Monty Mole","rarity":"uncommon","id":"monty-mole","subtitle":"Racer","details":"The burrowing, rock-throwing Monty Mole popped out of the ground to race in Mario Kart Tour in 2019, and later in World.","image":"https://mario.wiki.gallery/images/e/e0/MKWorld_Monty_Mole.jpg"},{"name":"Dixie Kong","rarity":"uncommon","id":"dixie-kong","subtitle":"Racer","details":"Dixie Kong, whose ponytail doubles as a helicopter, raced in Mario Kart only in Tour, joining the grid in 2019.","image":"https://mario.wiki.gallery/images/c/ce/MKT_Dixie_Kong.jpg"},{"name":"Captain Toad","rarity":"uncommon","id":"captain-toad","subtitle":"Racer","details":"Captain Toad, the backpack-wearing leader of the Toad Brigade, is a separate racer from regular Toad in Mario Kart Tour.","image":"assets/sets/compress/mkrt__captain-toad.webp"},{"name":"Nabbit","rarity":"uncommon","id":"nabbit","subtitle":"Racer","details":"The item-stealing rabbit Nabbit, who cannot use power-ups of his own in his home games, became a Tour racer in 2019.","image":"assets/sets/compress/mkrt__nabbit.webp"},{"name":"King Bob-omb","rarity":"uncommon","id":"king-bob-omb","subtitle":"Racer","details":"The moustached king of the Bob-ombs, first fought atop a mountain in Mario 64, became a playable Tour racer in 2019.","image":"https://mario.wiki.gallery/images/b/b4/MKT_King_Bob-omb.jpg"},{"name":"Mario Circuit 1","rarity":"uncommon","id":"mario-circuit-1","subtitle":"Course","details":"The first Mario Kart course of all: a simple paved circuit from Super Mario Kart with gentle bends, grass verges and pipe barriers.","image":"https://vignette.wikia.nocookie.net/mariokart/images/9/93/MKT_Mario_Circuit.jpg/revision/latest?cb=20191005165755"},{"name":"Donut Plains 1","rarity":"uncommon","id":"donut-plains-1","subtitle":"Course","details":"A lakeside plains course from Super Mario Kart, looping around the water with dirt patches and Monty Moles bursting from the ground.","image":"https://vignette.wikia.nocookie.net/mariokart/images/0/0f/Donut_plains_1_tour.png/revision/latest?cb=20200325160723"},{"name":"Ghost Valley 1","rarity":"uncommon","id":"ghost-valley-1","subtitle":"Course","details":"A rickety plank course suspended over darkness in Super Mario Kart, its narrow wooden boards full of holes and patrolled by Boos.","image":"https://vignette.wikia.nocookie.net/mariokart/images/b/b2/SuperMarioKart-GhostValley1.png/revision/latest?cb=20140625215912"},{"name":"Bowser Castle 1 (SMK)","rarity":"uncommon","id":"bowser-castle-1-smk","subtitle":"Course","details":"Super Mario Kart's first lava castle: tight stone corridors, sharp right angles, Thwomps and pools of lava beside the racing line.","image":"https://vignette.wikia.nocookie.net/mariokart/images/8/80/SuperMarioKart-BowserCastle1.png/revision/latest?cb=20140625220119"},{"name":"Mario Circuit 2","rarity":"uncommon","id":"mario-circuit-2","subtitle":"Course","details":"A trickier second Mario Circuit from Super Mario Kart, adding a jump ramp and tighter corners to the original's simple paved layout.","image":"https://mario.wiki.gallery/images/f/f1/MK7-SFC-MC.png"},{"name":"Koopa Troopa Beach (N64)","rarity":"uncommon","id":"koopa-troopa-beach-n64","subtitle":"Course","details":"A tropical beach circuit in Mario Kart 64 with a rock-arch shortcut, a waterfall and sidestepping crabs along the shoreline.","image":"https://vignette.wikia.nocookie.net/mariokart/images/d/d0/Koopa_Troopa_Beach_MK7_%28Koopa_Troopa_Racing%29.png/revision/latest?cb=20111218145644"},{"name":"Kalimari Desert","rarity":"uncommon","id":"kalimari-desert","subtitle":"Course","details":"A desert loop in Mario Kart 64 where the track crosses a working railway twice — and the train does not stop for racers.","image":"https://vignette.wikia.nocookie.net/mariokart/images/2/2e/Kalimari_Desert_in_MK8DX.jpg/revision/latest?cb=20221119201610"},{"name":"Frappe Snowland","rarity":"uncommon","id":"frappe-snowland","subtitle":"Course","details":"A snowy Mario Kart 64 course lined with snowmen that stop karts dead, plus a slippery bridge and a frozen river crossing.","image":"https://mario.wiki.gallery/images/d/de/MKT_Frappe_Snowland_Scene.jpg"},{"name":"Wario Stadium (N64)","rarity":"uncommon","id":"wario-stadium-n64","subtitle":"Course","details":"A huge dirt stadium in Mario Kart 64 built for Wario, packed with humps and jumps under floodlights and a giant screen.","image":"https://vignette.wikia.nocookie.net/mariokart/images/c/c6/Toad_%26_Mario_%28Wario_Stadium%29.png/revision/latest?cb=20160312204546"},{"name":"Peach Circuit","rarity":"uncommon","id":"peach-circuit","subtitle":"Course","details":"Super Circuit's bright opener, a clean paved circuit in Peach's colours with wide bends made for learning the game's drifting.","image":"https://vignette.wikia.nocookie.net/mariokart/images/5/5a/MarioKartDS_GBAPeachCircuit.png/revision/latest?cb=20150419205607"},{"name":"Shy Guy Beach","rarity":"uncommon","id":"shy-guy-beach","subtitle":"Course","details":"A pirate-haunted beach in Super Circuit where Shy Guy galleons offshore fire cannonballs onto the sand as racers pass.","image":"https://vignette.wikia.nocookie.net/mariokart/images/a/ad/ShyGuyBeach_MKWii.jpg/revision/latest?cb=20140505151445"},{"name":"Riverside Park","rarity":"uncommon","id":"riverside-park","subtitle":"Course","details":"A leafy park course in Super Circuit with wooden bridges over the river, waterfalls and tight turns between the trees.","image":"https://vignette.wikia.nocookie.net/mariokart/images/1/1a/Riverside_Park_in_MK8DX_2.0.jpg/revision/latest?cb=20230302203550"},{"name":"Bowser Castle 1 (GBA)","rarity":"uncommon","id":"bowser-castle-1-gba","subtitle":"Course","details":"Super Circuit's first lava castle: stone lanes over molten rock, with fire bars and tight corners setting the template for four.","image":"https://vignette.wikia.nocookie.net/mariokart/images/1/18/GBA_Bowser_Castle_1_%28Overview%29_-_Mario_Kart_7.jpeg/revision/latest?cb=20200112014034"},{"name":"Mario Circuit (GBA)","rarity":"uncommon","id":"mario-circuit-gba","subtitle":"Course","details":"Super Circuit's Mario Circuit, a flowing paved course with a loop-the-loop section and generous run-offs beside Peach's castle grounds.","image":"https://vignette.wikia.nocookie.net/mariokart/images/7/78/MK8_GBAMarioCircuit.jpg/revision/latest?cb=20150406154413"},{"name":"Luigi Circuit (GCN)","rarity":"uncommon","id":"luigi-circuit-gcn","subtitle":"Course","details":"Double Dash's opener: a figure-of-eight stadium circuit where the track crosses itself and a Chain Chomp guards the infield.","image":"https://vignette.wikia.nocookie.net/mariokart/images/7/7e/Luigi_Circuit_%28GCN%29_-_2.png/revision/latest?cb=20140604093222"},{"name":"Dry Dry Desert","rarity":"uncommon","id":"dry-dry-desert","subtitle":"Course","details":"A desert course in Double Dash with a sinking sand pit at its centre, Pokeys on the straights and ancient ruins at the edges.","image":"https://vignette.wikia.nocookie.net/mariokart/images/0/01/MK8_GCNDryDryDesert.jpg/revision/latest?cb=20150415062329"},{"name":"Mushroom Bridge","rarity":"uncommon","id":"mushroom-bridge","subtitle":"Course","details":"A busy bridge course in Double Dash, racing over arched spans and through tunnels alongside traffic on the highway below.","image":"https://vignette.wikia.nocookie.net/mariokart/images/3/32/Mushroom_Bridge.png/revision/latest?cb=20200804152202"},{"name":"Mario Circuit (GCN)","rarity":"uncommon","id":"mario-circuit-gcn","subtitle":"Course","details":"Double Dash's Mario Circuit races past Peach's Castle grounds, with Goombas, Piranha Plants and a wide esses section.","image":"https://vignette.wikia.nocookie.net/mariokart/images/3/32/MKDD_Mario_Circuit_2.png/revision/latest?cb=20160909010307"},{"name":"Waluigi Stadium","rarity":"uncommon","id":"waluigi-stadium","subtitle":"Course","details":"Waluigi's dirt stadium in Double Dash, a muddy arena of humps, fire bars and Piranha Plant obstacles under the lights.","image":"https://vignette.wikia.nocookie.net/mariokart/images/7/7a/MKDD_Waluigi_Stadium_1.png/revision/latest?cb=20160909035706"},{"name":"Figure-8 Circuit","rarity":"uncommon","id":"figure-8-circuit","subtitle":"Course","details":"Mario Kart DS's gentle opener, a smooth figure-of-eight circuit that crosses over itself on a bridge, built for clean racing.","image":"https://vignette.wikia.nocookie.net/mariokart/images/d/dd/F8CircuitDS.png/revision/latest?cb=20110103154228"},{"name":"Yoshi Falls","rarity":"uncommon","id":"yoshi-falls","subtitle":"Course","details":"A short, looping course in Mario Kart DS wrapped around a waterfall, where the water pushes karts toward the outside of the bend.","image":"https://vignette.wikia.nocookie.net/mariokart/images/8/81/Yoshi_Falls_Overview_-_Mario_Kart_Wii.png/revision/latest?cb=20120317174933"},{"name":"Cheep Cheep Beach","rarity":"uncommon","id":"cheep-cheep-beach","subtitle":"Course","details":"A tropical beach in Mario Kart DS with shallow lagoons, wooden piers and crabs wandering the sand at the water's edge.","image":"https://vignette.wikia.nocookie.net/mariokart/images/f/fa/MK8DSCheepCheepBeach.png/revision/latest?cb=20150412112245"},{"name":"Luigi's Mansion (DS)","rarity":"uncommon","id":"luigis-mansion-ds","subtitle":"Course","details":"A race through the grounds of Luigi's haunted mansion in Mario Kart DS, past Boos, muddy gardens and moving furniture inside.","image":"https://vignette.wikia.nocookie.net/mariokart/images/6/67/MKDS_Luigi%27s_Mansion_Intro.png/revision/latest?cb=20220226011452"},{"name":"Luigi Circuit (Wii)","rarity":"uncommon","id":"luigi-circuit-wii","subtitle":"Course","details":"Mario Kart Wii's friendly opener, a wide stadium circuit with gentle banks where a giant Luigi statue watches over the track.","image":"https://vignette.wikia.nocookie.net/mariokart/images/3/3d/Luigi_Circuit_Wii_Mirror.png/revision/latest?cb=20230901221452"},{"name":"Toad's Factory","rarity":"uncommon","id":"toads-factory","subtitle":"Course","details":"An industrial course in Mario Kart Wii racing through a Toad-run factory, dodging conveyor belts, crushers and muddy yards.","image":"https://vignette.wikia.nocookie.net/mariokart/images/0/09/Toad%27s_Factory_Image_MKWii.webp/revision/latest/scale-to-width-down/512"},{"name":"Mario Circuit (Wii)","rarity":"uncommon","id":"mario-circuit-wii","subtitle":"Course","details":"Mario Kart Wii's home circuit loops around Peach's Castle and its lake, with Chain Chomps staked in the castle grounds.","image":"https://vignette.wikia.nocookie.net/mariokart/images/1/19/Mario_Circuit_-_Mario_Kart_Wii_screenshot.jpg/revision/latest?cb=20200906011758"},{"name":"Daisy Circuit","rarity":"uncommon","id":"daisy-circuit","subtitle":"Course","details":"A seaside town circuit in Mario Kart Wii at sunset, circling a lighthouse and a harbour statue of Luigi and Daisy.","image":"https://vignette.wikia.nocookie.net/mariokart/images/a/ad/Mario_Kart_8_Deluxe_Daisy_Circuit.png/revision/latest?cb=20240203155822"},{"name":"Toad Circuit","rarity":"uncommon","id":"toad-circuit","subtitle":"Course","details":"Mario Kart 7's bright opener, a simple kart-shaped circuit with a glider ramp giving early racers their first taste of flight.","image":"https://vignette.wikia.nocookie.net/mariokart/images/a/a0/Toad_Circuit_in_MK8DX.jpg/revision/latest?cb=20221119195427"},{"name":"Daisy Hills","rarity":"uncommon","id":"daisy-hills","subtitle":"Course","details":"A rolling hills course in Mario Kart 7 past windmills and hot-air balloons, gliding down from a hilltop village to the valley.","image":"https://vignette.wikia.nocookie.net/mariokart/images/4/4e/MKT_Daisy_Hills.jpg/revision/latest?cb=20191005165632"},{"name":"Cheep Cheep Lagoon","rarity":"uncommon","id":"cheep-cheep-lagoon","subtitle":"Course","details":"A lagoon course in Mario Kart 7 that dives underwater through clam shells and caves, racing fish on their own turf.","image":"https://vignette.wikia.nocookie.net/mariokart/images/e/ed/Cheep_Cheep_Lagoon_Image_MK7.webp/revision/latest?cb=20230928172625"},{"name":"Shy Guy Bazaar","rarity":"uncommon","id":"shy-guy-bazaar","subtitle":"Course","details":"A night market course in Mario Kart 7, racing through a Shy Guy bazaar's stalls and gliding over rooftops under the lamps.","image":"https://vignette.wikia.nocookie.net/mariokart/images/9/9a/Shy_Guy_Bazaar_Image_MK7.webp/revision/latest/scale-to-width-down/512"},{"name":"Water Park","rarity":"uncommon","id":"water-park","subtitle":"Course","details":"A seaside amusement park in Mario Kart 8, racing past rollercoasters and diving underwater beneath the boardwalk rides.","image":"https://vignette.wikia.nocookie.net/mariokart/images/8/8c/MK8_WaterParkCourse.jpg/revision/latest?cb=20150331101155"},{"name":"Sweet Sweet Canyon","rarity":"uncommon","id":"sweet-sweet-canyon","subtitle":"Course","details":"A candy canyon in Mario Kart 8 made of cake, doughnuts and ice cream, with a glider flight over a chocolate landscape.","image":"https://vignette.wikia.nocookie.net/mariokart/images/4/46/640px-MK8SweetSweetCanyon_course.png/revision/latest?cb=20150331112910"},{"name":"Thwomp Ruins","rarity":"uncommon","id":"thwomp-ruins","subtitle":"Course","details":"Ancient ruins in Mario Kart 8 where giant Thwomps roll down the track and the anti-gravity walls are crumbling temples.","image":"https://vignette.wikia.nocookie.net/mariokart/images/7/7d/Iggy-ThwompRuins-MK8.jpg/revision/latest?cb=20150331133722"},{"name":"Mario Circuit (MK8)","rarity":"uncommon","id":"mario-circuit-mk8","subtitle":"Course","details":"Mario Kart 8's home circuit twists into a Möbius strip, racing upside down over Peach's Castle on an anti-gravity loop.","image":"https://vignette.wikia.nocookie.net/mariokart/images/0/0f/20130611213511%21MK8_Mario_Circuit.jpg/revision/latest?cb=20140307142150"},{"name":"Sky-High Sundae","rarity":"uncommon","id":"sky-high-sundae","subtitle":"Course","details":"A dessert course floating in the sky, racing over ice-cream scoops, wafers and a giant sundae in the Booster Course Pass.","image":"https://vignette.wikia.nocookie.net/mariokart/images/e/e9/Sky-High_Sundae_in_MK8DX.jpg/revision/latest?cb=20221119203112"},{"name":"Yoshi's Island","rarity":"uncommon","id":"yoshis-island","subtitle":"Course","details":"A course styled on Yoshi's Island in the Booster Course Pass, with craft-paper hills, Shy Guys and a giant Hootie the Blue Fish.","image":"https://vignette.wikia.nocookie.net/mariokart/images/7/77/Huffin_Puffins_on_Yoshi%27s_Island.webp/revision/latest?cb=20230403065542"},{"name":"Squeaky Clean Sprint","rarity":"uncommon","id":"squeaky-clean-sprint","subtitle":"Course","details":"A bathroom course in the Booster Course Pass, shrunk-down racers speeding around a bathtub, sink and rubber duck.","image":"https://vignette.wikia.nocookie.net/mariokart/images/b/b8/Squeaky_Clean_Sprint_Mirror_in_MK8DX.png/revision/latest?cb=20230911204124"},{"name":"New York Minute","rarity":"uncommon","id":"new-york-minute","subtitle":"Course","details":"A city course from Mario Kart Tour racing through New York's streets and Central Park beneath the Manhattan skyline.","image":"https://vignette.wikia.nocookie.net/mariokart/images/a/ae/New_York_Minute_Mirror_in_MK8DX.png/revision/latest?cb=20230908233454"},{"name":"Tokyo Blur","rarity":"uncommon","id":"tokyo-blur","subtitle":"Course","details":"A city course from Mario Kart Tour racing across Tokyo's Rainbow Bridge and through its neon-lit downtown streets.","image":"https://vignette.wikia.nocookie.net/mariokart/images/b/b5/Tokyo_Blur_MK8DX_.jpg/revision/latest?cb=20220812135533"},{"name":"Paris Promenade","rarity":"uncommon","id":"paris-promenade","subtitle":"Course","details":"A city course from Mario Kart Tour racing past the Eiffel Tower and Arc de Triomphe along Paris's grand boulevards.","image":"https://vignette.wikia.nocookie.net/mariokart/images/0/0f/Paris_Promenade_Main_Image.jpg/revision/latest?cb=20221025035658"},{"name":"London Loop","rarity":"uncommon","id":"london-loop","subtitle":"Course","details":"A city course from Mario Kart Tour racing past Big Ben, the London Eye and Buckingham Palace on the Thames embankment.","image":"https://vignette.wikia.nocookie.net/mariokart/images/9/9f/London_Loop_Mirror_in_MK8DX.png/revision/latest?cb=20230905011655"},{"name":"Mario Bros. Circuit","rarity":"uncommon","id":"mario-bros-circuit","subtitle":"Course","details":"Mario Kart World's desert opener, a canyon circuit in the open world with mesas, a diner and wide, welcoming corners.","image":"https://vignette.wikia.nocookie.net/mariokart/images/e/e6/1600px-MKWorld_Mario_Bros_Circuit_View_1.webp.png/revision/latest?cb=20260129195756"},{"name":"Crown City","rarity":"uncommon","id":"crown-city","subtitle":"Course","details":"A coastal city course in Mario Kart World, racing from downtown streets to the docks beneath the city's crown tower.","image":"https://vignette.wikia.nocookie.net/mariokart/images/8/8e/MKWD_CrownCity.png/revision/latest?cb=20260406195121"},{"name":"Whistlestop Summit","rarity":"uncommon","id":"whistlestop-summit","subtitle":"Course","details":"A mountain railway course in Mario Kart World, racing alongside a steam train through a snowy summit town and tunnels.","image":"https://vignette.wikia.nocookie.net/mariokart/images/6/66/1200px-MKWorld_Whistlestop_View.png/revision/latest?cb=20260402201044"},{"name":"DK Spaceport","rarity":"uncommon","id":"dk-spaceport","subtitle":"Course","details":"A rocket launch site course in Mario Kart World, racing up the launch tower roads as a Donkey Kong-branded rocket waits.","image":"https://mario.wiki.gallery/images/thumb/7/75/NM_MKWorld_DK_Spaceport.png/320px-NM_MKWorld_DK_Spaceport.png"},{"name":"Battle Course 1 (SMK)","rarity":"uncommon","id":"battle-course-1-smk","subtitle":"Battle Course","details":"One of Super Mario Kart's four original battle arenas: a compact walled square where balloon battles first took shape.","image":"assets/sets/compress/mkrt__battle-course-1-smk.webp"},{"name":"Battle Course 3 (SMK)","rarity":"uncommon","id":"battle-course-3-smk","subtitle":"Battle Course","details":"A Super Mario Kart battle arena with an open middle for head-on clashes and wall-lined edges for quick escapes.","image":"https://mario.wiki.gallery/images/d/d6/SMK_Battle_Course_3_Screenshot.png"},{"name":"Battle Course 4 (SMK)","rarity":"uncommon","id":"battle-course-4-smk","subtitle":"Battle Course","details":"The last of Super Mario Kart's four arenas, a tight walled battleground from the mode that started Mario Kart battles.","image":"assets/sets/compress/mkrt__battle-course-4-smk.webp"},{"name":"Battle Course 1 (GBA)","rarity":"uncommon","id":"battle-course-1-gba","subtitle":"Battle Course","details":"A Super Circuit battle arena in the original's spirit: simple walls, tight corners and nowhere to camp for long.","image":"https://mario.wiki.gallery/images/b/bf/Battlecourse1gbaMK7.png"},{"name":"Battle Course 2 (GBA)","rarity":"uncommon","id":"battle-course-2-gba","subtitle":"Battle Course","details":"One of Super Circuit's four battle arenas, a compact walled ground built for quick, close-range item fights on the handheld.","image":"https://mario.wiki.gallery/images/8/8a/MKSC_Battle_Course_2_Screenshot.png"},{"name":"Battle Course 3 (GBA)","rarity":"uncommon","id":"battle-course-3-gba","subtitle":"Battle Course","details":"A Super Circuit battle arena mixing open straights with wall cover, small and fast like all of the game's arenas.","image":"assets/sets/compress/mkrt__battle-course-3-gba.webp"},{"name":"Battle Course 4 (GBA)","rarity":"uncommon","id":"battle-course-4-gba","subtitle":"Battle Course","details":"Super Circuit's fourth battle arena, another tight, wall-divided battleground from the handheld's balloon battles.","image":"https://mario.wiki.gallery/images/5/56/MKSC_Battle_Course_4_Screenshot.png"},{"name":"Block City","rarity":"uncommon","id":"block-city","subtitle":"Battle Course","details":"A city-block battle arena in Double Dash, a grid of streets and pillars that turns every corner into an ambush.","image":"https://mario.wiki.gallery/images/1/11/MKDD_Block_City.png"},{"name":"Nintendo GameCube","rarity":"uncommon","id":"nintendo-gamecube","subtitle":"Battle Course","details":"A battle arena shaped like a giant GameCube console in Double Dash, disc lid, handle and all, raced on its top surface.","image":"https://vignette.wikia.nocookie.net/mariokart/images/2/27/Mario_790screen008.jpg/revision/latest?cb=20090614001516"},{"name":"Coin","rarity":"uncommon","id":"coin","subtitle":"Item","details":"A gold coin that tops up the driver's coin count, nudging top speed a little higher with each one held. Trackside since Super Mario Kart.","image":"https://mario.wiki.gallery/images/0/0f/MKT_Icon_Coin.png"},{"name":"Feather (Cape Feather)","rarity":"uncommon","id":"feather-cape-feather","subtitle":"Item","details":"A feather that launches the kart into a high spinning leap, clearing hazards and shortcuts in Super Mario Kart, where it first appeared.","image":"https://mario.wiki.gallery/images/9/98/MKT_Icon_Feather.png"},{"name":"Poison Mushroom","rarity":"uncommon","id":"poison-mushroom","subtitle":"Item","details":"A nasty mushroom that penalises any racer who runs into it. In Super Mario Kart it was Luigi's CPU-only special, never a regular player item.","image":"assets/sets/compress/mkrt__poison-mushroom.webp"},{"name":"Fireball","rarity":"uncommon","id":"fireball","subtitle":"Item","details":"A bouncing ball of fire used as a rolling hazard. It began as Bowser's CPU-only special in Super Mario Kart and became playable in Double Dash!!.","image":"assets/sets/compress/mkrt__fireball.webp"},{"name":"Yoshi's Egg","rarity":"uncommon","id":"yoshis-egg","subtitle":"Item","details":"An egg that homes in on a rival and cracks open in a spill of items. It started as Yoshi's CPU special in Super Mario Kart.","image":"https://mario.wiki.gallery/images/b/be/MKT_Icon_Yoshi%27s_Egg.png"},{"name":"Birdo's Egg","rarity":"uncommon","id":"birdos-egg","subtitle":"Item","details":"Birdo's pink-spotted egg from Double Dash!!, a special item that chases down the racer ahead and bursts open in a scatter of items.","image":"https://mario.wiki.gallery/images/6/66/MKT_Icon_Birdo%27s_Egg.png"},{"name":"Heart","rarity":"uncommon","id":"heart","subtitle":"Item","details":"Peach and Daisy's Double Dash!! special: two hearts orbit the kart, catching hazards thrown at it and turning them into items of their own.","image":"https://mario.wiki.gallery/images/c/c4/MKDD_Heart.png"},{"name":"Giant Banana","rarity":"uncommon","id":"giant-banana","subtitle":"Item","details":"Donkey Kong and Diddy Kong's Double Dash!! special: an oversized peel that splits into three regular bananas when a racer runs into it.","image":"https://mario.wiki.gallery/images/8/8c/MKT_Icon_Giant_Banana.png"},{"name":"Bowser's Shell","rarity":"uncommon","id":"bowsers-shell","subtitle":"Item","details":"Bowser's oversized shell special from Double Dash!!, a giant green wrecking ball that bowls through racers and bounces off the walls.","image":"https://mario.wiki.gallery/images/8/81/MKT_Icon_Bowser%27s_Shell.png"},{"name":"Chain Chomp","rarity":"uncommon","id":"chain-chomp","subtitle":"Item","details":"Baby Mario and Baby Luigi's Double Dash!! special: a chained Chomp drags the kart forward at speed, flattening anyone in its path.","image":"https://mario.wiki.gallery/images/7/77/MKDD_Chain_Chomp.png"},{"name":"POW Block","rarity":"uncommon","id":"pow-block","subtitle":"Item","details":"Triggers a shockwave that spins out every rival up ahead who is on the ground when it lands. The POW Block first appeared in Mario Kart Wii.","image":"assets/sets/compress/mkrt__pow-block.webp"},{"name":"Thunder Cloud","rarity":"uncommon","id":"thunder-cloud","subtitle":"Item","details":"A storm cloud that speeds its holder up but strikes them with lightning unless it is passed to a rival by bumping them. A Mario Kart Wii one-off.","image":"https://mario.wiki.gallery/images/1/19/MKW_Thunder_Cloud_Artwork.png"},{"name":"Steel Driver","rarity":"uncommon","id":"steel-driver","subtitle":"Vehicle","details":"A kart styled after a submarine, propeller and all, in a nod to Nintendo's Steel Diver. It is one of Mario Kart 8's heavier, deep-blue bodies.","image":"https://mario.wiki.gallery/images/e/e7/MKT_Steel_Driver.jpg"},{"name":"Tri-Speeder","rarity":"uncommon","id":"tri-speeder","subtitle":"Vehicle","details":"A three-wheeled sport kart that trades a front wheel for a sharp, leaning trike layout. The Tri-Speeder first appeared in Mario Kart 8.","image":"https://mario.wiki.gallery/images/5/56/TrispeederBodyMK8.png"},{"name":"Badwagon","rarity":"uncommon","id":"badwagon","subtitle":"Vehicle","details":"A chunky, boxy wagon of a kart with a high ride and heavy looks, despite its name being pure mischief. The Badwagon appears in Mario Kart 8.","image":"https://mario.wiki.gallery/images/c/c2/BadwagonBodyMK8.png"},{"name":"Prancer","rarity":"uncommon","id":"prancer","subtitle":"Vehicle","details":"An elegant, vintage-styled kart with sweeping curves and a classic roadster air, dressed in pink and white. The Prancer appears in Mario Kart 8.","image":"https://mario.wiki.gallery/images/7/7b/MKT_Prancer.jpg"},{"name":"Biddybuggy","rarity":"uncommon","id":"biddybuggy","subtitle":"Vehicle","details":"A tiny kart shaped like a Biddybuggy, the propeller-topped beetle enemy, shrunk down to kart size. The Biddybuggy first appeared in Mario Kart 8.","image":"https://mario.wiki.gallery/images/4/45/BiddybuggyBodyMK8.png"},{"name":"Landship","rarity":"uncommon","id":"landship","subtitle":"Vehicle","details":"A kart built like a little sailing ship, bow, mast and all, modelled on Bowser's airships. The Landship first appeared in Mario Kart 8.","image":"https://mario.wiki.gallery/images/6/6d/LandshipBodyMK8.png"},{"name":"Sneeker","rarity":"uncommon","id":"sneeker","subtitle":"Vehicle","details":"A kart shaped like a trainer shoe, laces, sole and all, built for a joke that never gets old. The Sneeker first appeared in Mario Kart 8.","image":"https://mario.wiki.gallery/images/b/b8/MK8_Toad_Red_Sneeker_Kart_Select.jpg"},{"name":"GLA","rarity":"uncommon","id":"gla","subtitle":"Vehicle","details":"A kart modelled on the real Mercedes-Benz GLA, a luxury SUV dropped into the Mushroom Kingdom as Mario Kart 8 download content.","image":"https://mario.wiki.gallery/images/c/c2/GLA-MK8.png"},{"name":"W 25 Silver Arrow","rarity":"uncommon","id":"w-25-silver-arrow","subtitle":"Vehicle","details":"A kart recreating Mercedes-Benz's 1934 W 25 Silver Arrow grand prix car, silver body and all, added to Mario Kart 8 as download content.","image":"https://mario.wiki.gallery/images/2/25/W25SilverArrow-MK8.png"},{"name":"300 SL Roadster","rarity":"uncommon","id":"300-sl-roadster","subtitle":"Vehicle","details":"A kart modelled on the classic Mercedes-Benz 300 SL Roadster, a 1950s open-top sports car, brought to Mario Kart 8 as download content.","image":"https://mario.wiki.gallery/images/f/f4/300SLRoadster_MK8.png"},{"name":"Tanooki Kart","rarity":"uncommon","id":"tanooki-kart","subtitle":"Vehicle","details":"A kart wearing the Tanooki Suit's ears and ringed tail, made as a partner body for Tanooki Mario. It was added to Mario Kart 8 as download content.","image":"https://mario.wiki.gallery/images/e/e0/MKT_Icon_TanookiKart.png"},{"name":"Streetle","rarity":"uncommon","id":"streetle","subtitle":"Vehicle","details":"A beetle-bodied city kart with round headlights and a bug-like shell, built for the streets. The Streetle was added to Mario Kart 8 as download content.","image":"https://mario.wiki.gallery/images/c/cf/MK8Streetle.png"},{"name":"P-Wing","rarity":"uncommon","id":"p-wing","subtitle":"Vehicle","details":"A winged kart named for the P-Wing power-up, all sharp angles and speed lines. The P-Wing was added to Mario Kart 8 as download content.","image":"https://mario.wiki.gallery/images/c/cd/MK8PWing.png"},{"name":"Standard Bike","rarity":"uncommon","id":"standard-bike","subtitle":"Vehicle","details":"The default bike body of Mario Kart 8: a straightforward sports motorcycle with no extremes, the baseline every other bike is compared to.","image":"https://mario.wiki.gallery/images/d/d7/MKWorld_Bike_Standard_Bike.png"},{"name":"The Duke","rarity":"uncommon","id":"the-duke","subtitle":"Vehicle","details":"A laid-back chopper-style bike with high handlebars and a long front fork, cruising rather than racing. The Duke appears in Mario Kart 8.","image":"https://mario.wiki.gallery/images/8/8a/TheDukeBodyMK8.png"},{"name":"Flame Rider","rarity":"uncommon","id":"flame-rider","subtitle":"Vehicle","details":"A muscular bike dressed in flame livery, built like a street racer with fire in its paintwork. The Flame Rider appears in Mario Kart 8.","image":"https://mario.wiki.gallery/images/3/31/FlameRiderBodyMK8.png"},{"name":"Varmint","rarity":"uncommon","id":"varmint","subtitle":"Vehicle","details":"A scrappy little trail bike with a rugged, rough-and-ready look, more scrambler than superbike. The Varmint first appeared in Mario Kart 8.","image":"https://mario.wiki.gallery/images/d/d0/VarmintBodyMK8.png"},{"name":"Mr. Scooty","rarity":"uncommon","id":"mr-scooty","subtitle":"Vehicle","details":"Mario Kart 8's tiny scooter bike, a cheerful little runabout with a step-through frame and the smallest silhouette on the bike roster.","image":"https://mario.wiki.gallery/images/1/18/MrScootyBodyMK8.png"},{"name":"City Tripper","rarity":"uncommon","id":"city-tripper","subtitle":"Vehicle","details":"A smart city scooter with an enclosed front and upright riding position, built for town rather than track. It came to Mario Kart 8 as download content.","image":"https://mario.wiki.gallery/images/2/2e/MK8_Pink_City_Tripper.png"},{"name":"All Cup Tour","rarity":"uncommon","id":"all-cup-tour","subtitle":"Cup","details":"Double Dash!!'s All Cup Tour ran all 16 of the game's courses back to back in random order - a marathon, not a normal cup.","image":"https://mario.wiki.gallery/images/4/44/All_Cup_Tour.png"},{"name":"Golden Dash Cup","rarity":"uncommon","id":"golden-dash-cup","subtitle":"Cup","details":"The first Booster Course Pass cup, the Golden Dash Cup arrived in Wave 1 in 2022, opening with Tour's Paris Promenade.","image":"https://mario.wiki.gallery/images/7/7e/MK8D_BCP_Golden_Dash_Emblem.png"},{"name":"Lucky Cat Cup","rarity":"uncommon","id":"lucky-cat-cup","subtitle":"Cup","details":"Wave 1 of the Booster Course Pass in 2022 added the Lucky Cat Cup, named for the maneki-neko and home to Ninja Hideaway.","image":"https://mario.wiki.gallery/images/1/18/MK8D_BCP_Lucky_Cat_Emblem.png"},{"name":"Turnip Cup","rarity":"uncommon","id":"turnip-cup","subtitle":"Cup","details":"The Turnip Cup arrived in Wave 2 of the Booster Course Pass in 2022, headlined by Waluigi Pinball's return from Mario Kart DS.","image":"https://mario.wiki.gallery/images/e/ea/MK8D_BCP_Turnip_Emblem.png"},{"name":"Propeller Cup","rarity":"uncommon","id":"propeller-cup","subtitle":"Cup","details":"Wave 2 of the Booster Course Pass in 2022 added the Propeller Cup, which introduced the brand-new course Sky-High Sundae.","image":"https://mario.wiki.gallery/images/a/ab/MK8D_BCP_Propeller_Emblem.png"},{"name":"Rock Cup","rarity":"uncommon","id":"rock-cup","subtitle":"Cup","details":"The Rock Cup arrived in Wave 3 of the Booster Course Pass in 2022, named for the Rock Mushroom power-up from Mario Galaxy 2.","image":"https://mario.wiki.gallery/images/6/66/MK8D_BCP_Rock_Emblem.png"},{"name":"Moon Cup","rarity":"uncommon","id":"moon-cup","subtitle":"Cup","details":"Wave 3 of the Booster Course Pass in 2022 added the Moon Cup, named for the 3-Up Moon and home to snowy Merry Mountain.","image":"https://mario.wiki.gallery/images/c/c2/MK8D_BCP_Moon_Emblem.png"},{"name":"Mario Kart Arcade GP 2","rarity":"uncommon","id":"mario-kart-arcade-gp-2","subtitle":"Game","details":"Mario Kart Arcade GP 2 returned to arcades in 2007, adding Mametchi from Tamagotchi along with new courses and items.","image":"https://mario.wiki.gallery/images/b/bf/Mario_Kart_Arcade_GP_2.jpg"},{"name":"Mario Kart Arcade GP VR","rarity":"uncommon","id":"mario-kart-arcade-gp-vr","subtitle":"Game","details":"Mario Kart Arcade GP VR put players inside the kart with a VR headset in 2017, throwing shells and hammers by hand.","image":"https://mario.wiki.gallery/images/thumb/a/a1/MKAGPVR_Key_Artwork.jpg/800px-MKAGPVR_Key_Artwork.jpg"},{"name":"Koopa Paratroopa","rarity":"common","id":"koopa-paratroopa","subtitle":"Racer","details":"The winged red-shelled Koopa raced only once, as a lightweight in Double Dash!! in 2003, and never returned to the grid.","image":"https://mario.wiki.gallery/images/d/d1/MK8_Paratroopa.png"},{"name":"Pac-Man","rarity":"common","id":"pac-man","subtitle":"Racer","details":"The arcade legend himself crossed over as a playable racer in Mario Kart Arcade GP in 2005, an arcade-only guest star.","image":"https://mario.wiki.gallery/images/1/1d/MKAGPDX_Pac-Man_artwork.jpg"},{"name":"Ms. Pac-Man","rarity":"common","id":"ms-pac-man","subtitle":"Racer","details":"Ms. Pac-Man joined Pac-Man as an arcade-only crossover racer in Mario Kart Arcade GP in 2005, complete with her signature bow.","image":"https://mario.wiki.gallery/images/2/2b/KartStandMsPacManMKAGP2.png"},{"name":"Blinky","rarity":"common","id":"blinky","subtitle":"Racer","details":"Blinky, the red ghost who has chased Pac-Man since 1980, became an arcade-only Mario Kart racer in Arcade GP in 2005.","image":"https://mario.wiki.gallery/images/0/06/Blinky.jpg"},{"name":"Mametchi","rarity":"common","id":"mametchi","subtitle":"Racer","details":"Mametchi, the best-known Tamagotchi character, crossed over as an arcade-only racer in Mario Kart Arcade GP 2 in 2007.","image":"https://mario.wiki.gallery/images/9/97/MKAGP2_Mametchi_alt.png"},{"name":"Mii","rarity":"common","id":"mii","subtitle":"Racer","details":"Your own avatar joined the racing in Mario Kart Wii in 2008, with your Mii's size deciding its weight class on the grid.","image":"https://vignette.wikia.nocookie.net/mariokart/images/4/4f/Mii_-_Mario_Kart_X.png/revision/latest?cb=20200504161811"},{"name":"Honey Queen","rarity":"common","id":"honey-queen","subtitle":"Racer","details":"The enormous queen of the bees from Super Mario Galaxy raced only in Mario Kart 7 in 2011, shrunk down to fit her kart.","image":"https://mario.wiki.gallery/images/thumb/4/48/Honey_Queen_MK7.png/320px-Honey_Queen_MK7.png"},{"name":"Wiggler","rarity":"common","id":"wiggler","subtitle":"Racer","details":"The friendly caterpillar who turns red with rage when stomped became a heavyweight racer in Mario Kart 7 in 2011.","image":"https://mario.wiki.gallery/images/thumb/7/75/MK8_Wiggler.png/320px-MK8_Wiggler.png"},{"name":"Lakitu","rarity":"common","id":"lakitu","subtitle":"Racer","details":"Not the referee with the start lights - this red-shelled Lakitu got out of the cloud and into a kart in Mario Kart 7 in 2011.","image":"https://mario.wiki.gallery/images/thumb/7/75/Lakitu_-_Mario_Kart_8.png/320px-Lakitu_-_Mario_Kart_8.png"},{"name":"Don-chan","rarity":"common","id":"don-chan","subtitle":"Racer","details":"Don-chan, the taiko drum mascot of Taiko no Tatsujin, crossed over as an arcade-only racer in Arcade GP DX in 2013.","image":"https://mario.wiki.gallery/images/4/41/MKAGPDX_Don-chan_artwork.jpg"},{"name":"Boomerang Bro","rarity":"common","id":"boomerang-bro","subtitle":"Racer","details":"The Boomerang Bro, who hurls curved boomerangs that return to him, became a separate playable Tour racer in 2019.","image":"https://mario.wiki.gallery/images/a/ad/MKT_Artwork_BoomerangBro.png"},{"name":"Fire Bro","rarity":"common","id":"fire-bro","subtitle":"Racer","details":"The red Fire Bro, who spits bouncing fireballs at Mario, became a separate playable racer in Mario Kart Tour in 2019.","image":"https://mario.wiki.gallery/images/thumb/3/3d/NSMBU_Fire_Bro_Artwork.png/512px-NSMBU_Fire_Bro_Artwork.png"},{"name":"Ice Bro","rarity":"common","id":"ice-bro","subtitle":"Racer","details":"The blue Ice Bro, who throws freezing ice balls, was a brand-new character type when he became a Tour racer in 2019.","image":"https://mario.wiki.gallery/images/2/26/MKWorld_Ice_Bro.png"},{"name":"Chargin' Chuck","rarity":"common","id":"chargin-chuck","subtitle":"Racer","details":"The football-geared Chargin' Chuck, an enemy since Super Mario World, became a racer in Mario Kart Tour in 2019.","image":"https://mario.wiki.gallery/images/b/b6/MKW_Chargin'_Chuck.png"},{"name":"Poochy","rarity":"common","id":"poochy","subtitle":"Racer","details":"Poochy, Yoshi's faithful dog who can run safely across lava and spikes, joined Mario Kart Tour late in its run, in 2023.","image":"https://mario.wiki.gallery/images/e/e5/MKT_Artwork_Poochy.png"},{"name":"Pianta","rarity":"common","id":"pianta","subtitle":"Racer","details":"A palm-tree-headed islander from Delfino Isle, the Pianta became a playable racer in Mario Kart World in 2025.","image":"https://mario.wiki.gallery/images/2/2f/Mario_Kart_World_Pianta.png"},{"name":"Pokey","rarity":"common","id":"pokey","subtitle":"Racer","details":"The stacked, spiky cactus who sways in the desert sun became a playable racer in Mario Kart World in 2025, segments and all.","image":"assets/sets/compress/mkrt__pokey.webp"},{"name":"Para-Biddybud","rarity":"common","id":"para-biddybud","subtitle":"Racer","details":"The winged, marching Para-Biddybud took its endless parade lap into a kart as a playable racer in Mario Kart World in 2025.","image":"assets/sets/compress/mkrt__para-biddybud.webp"},{"name":"Penguin","rarity":"common","id":"penguin","subtitle":"Racer","details":"The chubby snow penguins of Mario's ice levels became playable racers in Mario Kart World in 2025, flippers and all.","image":"https://mario.wiki.gallery/images/c/cf/MKT_Penguin.png"},{"name":"Spike","rarity":"common","id":"spike","subtitle":"Racer","details":"Spike, the green enemy who rolls giant spiked balls out of his mouth, became a playable racer in Mario Kart World in 2025.","image":"https://mario.wiki.gallery/images/7/74/MKWorld_Spike.png"},{"name":"Sidestepper","rarity":"common","id":"sidestepper","subtitle":"Racer","details":"The Sidestepper crab has been scuttling sideways since the original Mario Bros. arcade game, and raced in World in 2025.","image":"https://mario.wiki.gallery/images/0/0c/MKWorld_Sidestepper.png"},{"name":"Snowman","rarity":"common","id":"snowman","subtitle":"Racer","details":"The Snowman - the Mr. Blizzard type who lobs snowballs from his bucket hat - became a racer in Mario Kart World in 2025.","image":"assets/sets/compress/mkrt__snowman.webp"},{"name":"Cataquack","rarity":"common","id":"cataquack","subtitle":"Racer","details":"The Cataquack duck flips racers into the air with its bill on Peach Beach, and became a racer itself in World in 2025.","image":"assets/sets/compress/mkrt__cataquack.webp"},{"name":"Fish Bone","rarity":"common","id":"fish-bone","subtitle":"Racer","details":"The skeletal Fish Bone, which falls apart and reassembles itself underwater, became a playable racer in Mario Kart World in 2025.","image":"assets/sets/compress/mkrt__fish-bone.webp"},{"name":"Dolphin","rarity":"common","id":"dolphin","subtitle":"Racer","details":"Dolphins carried Mario through the water in Super Mario World; in Mario Kart World in 2025, one finally got a kart.","image":"assets/sets/compress/mkrt__dolphin.webp"}]});
